#!/usr/bin/env perl
# VERSION 2.0.41

use strict;
use warnings;
use File::Copy;                                 # Module for copying files. Used to replace output file with temp cleaned-up file.
use File::Spec;                                 # Absolute paths, to tell whether -o= names the input file (Windows).
use utf8;                                       # Required to process Unicode text (the phonetic symbols).
use Encode;                                     # Module for dealing with different text encodings, such as UTF-8.
use open qw(:std :encoding(UTF-8));
use Getopt::Long qw(:config no_auto_abbrev);    # Module for processing command line options.
use Term::ANSIColor qw(colored);                # For color output (works on Linux, macOS, and modern Windows terminals).
use Unicode::Normalize ();                      # Every file Perkins writes is Unicode NFC.

#################################################################################
#                  SUBROUTINE: WINDOWS-SAFE COLOR WRAPPER                       #
#################################################################################
# Both legacy Windows cmd.exe and PowerShell display raw ANSI/VT100
# escape codes as literal clutter (e.g. "←[1;32m") instead of actual colors,
# rather than reliably processing them -- so rather than try to detect
# specific "known good" Windows terminals (which proved unreliable), color
# is simply disabled outright on Windows. Linux and macOS terminals are
# unaffected and keep full color output.
our $_use_color = ( $^O eq "MSWin32" ) ? 0 : 1;

sub safe_colored {
     my ( $text, @rest ) = @_;
     return $text unless $_use_color;
     return colored( $text, @rest );
}
use Roman;                                      # Convert Roman numerals
use Lingua::ES::Numeros;                        # Module to convert numerals to Spanish text.


my $version = "2.0.41";
