# @BUILTIN_PHRASES: multiword names read as one Spanish word. Each
# entry is [ pattern, respelling ]; the pattern is matched without regard to
# case, and its words may be separated by spaces, underscores (FreeLing
# multiwords) and apostrophes. In running text the phrase is replaced; with
# --tokens the reading goes on the first token of the phrase.
our $PH_SEP = qr/[\s_'’]+/;
our @BUILTIN_PHRASES = (
     [ qr/guns${PH_SEP}(?:n|and|&|y)${PH_SEP}roses/i, 'gansenróses' ],
