     [ qr/scrum${PH_SEP}master/i, 'escrám máster' ],
);
our $mfa_phoneset_file   = '';  # --mfa-phoneset: override the built-in inventory
our $mfa_apply_rules     = 0;    # --mfa-rules: apply the MFA dictionary's own allophony. Default OFF -- see changelog.    # Produces a word-level Grapheme-to-Phoneme (MFA) dictionary: one entry per
                                 #   line, where EACH LINE CONSISTS OF THE ORTHOGRAPHIC WORD
                                 #   STRIPPED OF ACCENT MARKS, A TAB SYMBOL, AND THEN THE INDIVIDUAL PHONEMES OF THE WORD IN IPA,
                                 #   WITH A SPACE BETWEEN EACH. For maximum compatibility with tools such as the
                                 #   Montreal Forced Aligner (MFA), the following symbols must
                                 #   be used instead of alternatives:
                                 #   a  e  i  o  u    p  t  k  b  d  ɡ    f  s  x    m  n  ɲ    l    ɾ  r    j  w    ʝ    tʃ
                                 #   The purpose of this is to populate a segment-level tier with phonemes.

our $mfa_force_running_text = 0; # Force -mfa to treat the input as RUNNING TEXT (many words per line): each
                                 #   line's real words are tokenized out and each gets its own deduplicated
                                 #   dictionary entry, accumulated across the whole file and written once at
                                 #   the end, instead of gluing an entire line into one headword. Overrides
                                 #   auto-detection. Mutually exclusive with $mfa_force_word_list (whichever
                                 #   is set LAST on the command line wins, same as any other -no* pair).
our $mfa_force_word_list    = 0; # Force -mfa to treat the input as an existing ONE-WORD-PER-LINE dictionary
                                 #   source (the original -mfa behavior: one dictionary entry per input line,
                                 #   keyed on the whole line). Overrides auto-detection.
our $mfa_input_is_running_text; # Set once, automatically or by the two flags above, right after the input
                                 #   file is opened and before it's read. undef until then. 1 = running text
                                 #   (tokenize/dedupe), 0 = one-word-per-line (original behavior).
our %mfa_running_text_dict = (); # Accumulator for running-text -mfa mode: orthographic word => phoneme
                                 #   string, populated during the main read loop and printed once, sorted,
                                 #   after the whole input file has been read.

our $phonword_format     = 0;    # Takes the orthographic word-level transcriptions produced by MFA and converts
                                 #   them into a one-item-per line format, where EACH LINE CONSISTS OF THE ORTHOGRAPHIC WORD
                                 #   WITH TILDES, A TAB, AND THE PHONEMIC TRANSCRIPTION AS A SINGLE WORD, WITH STRESS AND SYLLABLE
                                 #   BOUNDARY MARKERS. The purpose of this is to populate the WORD-LEVEL orthographic and phonemic
                                 #   transcription tiers in Praat.



our $vrt_format          = 0;    # The -vrt preset: a word list, one transcribed word per line (with -sas, one
                                 # syllable per line), without pauses, syllabified by word, stress marked with
                                 # an accent. It overrides most other settings, so turn it off to choose them.

our $word_list           = 0;    # Select settings for producing output that is easy to process at the word level
                                 #   (syllables separated by a dot, words separated by a space). Doesn't itself
                                 #   specify a transcription output format, so it can be combined with one of the
                                 #   output_* variables above.

our $coscach_mode        = 0;    # Select settings tuned for the COSCACH/CODICACH corpus transcription conventions
                                 #   (retracted affricates without ligatures, dental diacritics, tilde-marked stress,
                                 #   syllable dots as spaces). This overrides most other settings, so turn it off to
                                 #   specify other options.

# USER OPTIONS - FORMAT OF TRANSCRIPTION OUTPUT
our $output_PHON   = 1;          # Set output to phonemic transcription
our $output_CV     = 0;          # Instead of outputting phonemes, output C (consonant) or V (vowel)
our $output_CVG    = 0;          # Instead of outputting phonemes, output C (consonant), V (vowel) or G (glide)
our $output_CVNLRG = 0;          # Instead of outputting phonemes, output Vowel, Nasal, Liquid, Rhotic,
                                 #    Glide or (misc) Consonant
our $output_manner = 0;          # Instead of outputting phonemes, output the manner of articulation
our $output_place  = 0;          # Instead of outputting phonemes, output the mode of articulation
our $voicing       = 0;          # Instead of outputting phonemes, output the voicing


# USER OPTIONS - FOR SPECIFIC PHONEMES
our $multichars              = 1;    # Represent certain phonemes using more than one character (e.g. use "t̠͡ʃ" instead of "ʧ")

# TR
our $tr_is_group             = 0;    # Treat /tr/ as a group. If on, it produces "t͡ɾ" with multichars and "ʂ" without it.

# CH + DZH
our $ch_dzh_retracted        = 0;    # Add retracted diacritic to the /t̠͡ʃ/ and /d̠͡ʒ/ digraphs (if /ʝ/ is not used)
our $use_ligatures           = 1;    # Use ligatures in /ʧ/ and /ʤ/ (/ʝ/)

#CH
our $use_one_char_ch_symbol  = 0;    # Use the /ʧ/ symbol to represent /ʧ/ regardless of the multichar setting. It was a dumb decision to link the two!

# YE
our $ye_phoneme_is_fricative = 1;    # Represent the phoneme "ye" (<ll> in "ella", <y> in "yo") with the palatal frictive symbol ʝ
                                     #    instead of the affricate ʤ
our $ye_phoneme_is_affricate = 0;    # MUST have opposite value of $ye_phoneme_is_fricative !
our $use_one_char_ye_symbol  = 1;    # Use the /ʝ/ symbol to represent /ʝ/ regardless of the multichar setting. It was a dumb decision to link the two!

# D + T
our $use_dental_diacr        = 1;    # Use dental diacritic with /d/ and /t/

# G
our $add_epenthetic_g        = 0;    # Add an epenthetic [g] before /w/. Traditionally believed ubiquitous in Chilean Spanish, but turns out to be rather uncommon.

# USER OPTIONS - FOR GLIDES
our $glides_with_diacritics = 0;     # 1 HERE is equivalent to turning both the following options on. If set here, that's unnecessary.
our $non_syl_u_with_u_diacr = 0;     # Represent the non-syllabic /u/ as /u̯/, not /w/
our $non_syl_i_with_i_diacr = 0;     # Represent the non-syllabic /i/ as /i̯/, not /j/

# USER OPTIONS - EASY SELECTION OF CH REPRESENTATION
# The standard system requires properly setting three variables to get the representation of "ch" that you want. This makes it much easier.
our $ch_is_single_char                  = 0; # -chsc        ʧ
our $ch_is_retracted_with_ligature      = 0; # -chrl        t̠͡ʃ
our $ch_is_retracted_no_ligature        = 0; # -chrnl       t̠ʃ
our $ch_not_retracted_with_ligature     = 0; # -chnrl       t͡ʃ
our $ch_not_retracted_no_ligature       = 0; # -chnrnl      tʃ

# USER OPTIONS - FOR PHONEMES IN GENERAL
our $space_between_phonemes   = 0;    # Separates phonemes with a space
our $word_plus_phonemes       = 0;    # Make the output format be the input word followed by a tab and the list of phonemes
                                      #   (implies space_between_phonemes is 1)

# USER OPTIONS - STRESS
our $stress_using_tildes = 0;        # If 1, mark stress with tildes on stressed vowels; if 0, mark it with IPA apostrophes.
our $no_stress_marks     = 0;        # Don't include any type of stress indication. Only for special cases.
our $non_ipa_apostrophes = 0;        # Use the standard orthographic apostrophe (') instead of the IPA one (which doesn't show in Praat)
                                     # Added in 376

# USER OPTIONS - SYLLABLES
our $insert_syllable_dots     = 1;    # Insert dots between each syllable
our $split_at_syllables       = 0;    # Put a newline at each syllable break
our $syllabify_by_sentence    = 1;    # Syllabifies by sentence instead of by word. This means "los hombres" > /lo.som.bres/
                                      # instead of /los om.bres/
our $syllable_dots_are_spaces = 0;    # Separate syllables with spaces instead of dots. Designed to facilitate processing
                                      #   and research on syllables in the Codicach, etc. (lets syllables be treated as words)

# USER OPTIONS - NARROW (ALLOPHONIC) TRANSCRIPTION
our $narrow_transcription     = 0;    # Apply Chilean Spanish phonologically-conditioned narrow-transcription rules
                                      #   (b/d/g spirantization, yeismo affrication, nasal place assimilation, vowel
                                      #   nasalization) on top of whatever phonemic output the current mode produces.
                                      #   Independent of output mode -- works the same way for -mfa, running text, etc.

# USER OPTIONS - PAUSES
our $ipa_pause_symbols    = 1;        # Use the IPA's | and ‖ method of representing pauses
our $ipa_long_pause_two_singles = 0;  # For long IPA pauses, use two single pause bars (||) instead of one#
                                      # double bar (‖).
our $add_comma_pauses     = 1;        # Commas are converted into short pauses:                 (.)
our $add_colon_pauses     = 1;        # Colons are converted into long pauses:                  (...)
our $add_semicolon_pauses = 1;        # Semicolons are converted into long pauses:              (...)
our $add_sentence_breaks  = 1;        # Periods are converted into absolute breaks:             ##
our $add_paragraph_breaks = 1;        # Paragraph breaks are converted into longest pause:      ###
                                      #    This can be in addition to newlines.
our $add_ellipsis_pauses  = 1;        # Ellipses are converted into a long pause:               (...)
our $add_bracket_pauses   = 1;        # Convert [ and ] into short pauses                       (.)
our $add_paren_pauses     = 1;        # Convert ( and ) into short pauses                       (.)

# USER OPTIONS - NUMBERS
our $numerals_to_words    = 1;        # Convert numerals (123) to words (uno dos tres)
our $num_symbol           = "·";      # Symbol used to replace numerals if that option is chosen
our $decimal_symbol       = ",";      # Which symbol separates whole numbers from fractions (the
                                      #  decimal point): "," or ".". The OTHER symbol is treated as
                                      #  the thousands (grouping) separator throughout number
                                      #  processing (currency, percentages, units, plain decimals).
                                      #  Default "," matches the existing Spanish/Chilean convention
                                      #  (e.g. "12,35" is twelve point thirty-five; "1.500" is one
                                      #  thousand five hundred). Set via --decimal-period/-dp or
                                      #  --decimal-comma/-dc.
our $narrow_year_ranges   = 1;        # Treat two consecutive 4-digit numbers separated by "-" as a range of years
                                      #  (e.g. "1900-1950" > "1900 a 1950") instead of an equation (1900 minus 1950)
                                      #  IF AND ONLY IF the second number is larger than the first.
our $broad_year_ranges    = 1;        # Treat two consecutive 1-4 digit numbers separated by "-" as a range of years
                                      #  (e.g. "211-300" > "211 a 300") instead of an equation (211 minus 300)
                                      #  IF AND ONLY IF the second number is larger than the first.
our $bc_dates_included    = 1;        # Remove restriction on second number having to be larger than the first from
                                      #  $narrow_year_ranges and $broad_year_ranges.
our $all_year_ranges      = 1;        # Process all date ranges (1-3 digit, 4 digit, BC dates).
our $times_with_colon     = 1;        # Process times - 1-2 numbers, a colon and two numbers.

# USER OPTIONS - ODD CHARACTERS       #
our $fix_umlauts          = 1;        # Change vowels with umlauts to bare vowels (except ü for diéresis)
our $fix_grave_accents    = 1;        # Change vowels with umlauts to bare vowels (tù, està > tú, está)
our $fix_circumflexes     = 1;        # Change vowels with circumflexes to bare vowels (hôstel > hostel)
our $fix_nasal_tildes     = 1;        # Change vowels with nasal tildes to bare vowels (S~ao > Sao)

# USER OPTIONS - SUBSTITUTIONS       #
our $moneda        = "pesos";        # String used to replace "$" character
our $rut_k_mode    = "letter";       # How to read RUT check digit K: "letter" (literal k) or "ka" (spoken)
our $slash         = "eslách";       # String used to replace "/" character
our $process_urls  = 1;              # Process URLs, treating them as linguistic strings.
our $process_email = 1;              # Process e-mail addresses, treating them as linguistic strings.

# NEW IN 0406 ->
our $name_for_v    = "becórta";      # Name for letter "v" to be used when spelling individual letters out.
                                     # Suggested values: "becórta", "bechíca", "úve" (with tilde on
                                     # accented syl. and written as one word).

# USER OPTIONS - MISC                #
our $keep_paragraphs          = 1;   # Keep paragraphs in the source text. Otherwise, output will be one big block.
our $vertical_output          = 0;   # Output contains one word per line.
our $list_mode                = '';  # Set in forcibly_set_variables(): 'words' (-owl, -vrt) or
                                    # 'syllables' (-sas, -osl); the list is cut from the finished
                                    # transcription by write_list_output().
our $triple_vowels_to_double = 1;   # Reduce three or more identical vowels ("aaa", "eee", "iii", etc.) to two.


