#    Do NOT modify ANY of the following values!   #
###################################################

our $cleanup_output_file = 1;         # WARNING Must ALWAYS be 1! After processing the input file and producing the output
                                      #         file, this option makes Perkins open the output file again to perform cleanup.

our $no_separate_cleanup_file = 1;    # WARNING Must ALWAYS be 1! Determines if the cleaned up version goes to a separate text#
                                      #         file or replaces the output file ONLY IN BETA MODE.

# OUTPUT: CLEANUP OPTIONS             #
our $preclean_orthographic = 1;       # WARNING Must ALWAYS be 1! Apply the clean-up routine for words in their orthographic form.
our $preclean_semiphonemic = 1;       # WARNING Must ALWAYS be 1! Apply the clean-up routine for words in their semi-phonemic form.
our $preclean_phonemic     = 0;       # WARNING NOT IMPLEMENTED YET! # Apply the clean-up routine for words in their phonemic form.

# INTERNAL VARIABLES THAT NEED INITIALIZED - DO NOT TOUCH THEM!
my $helpme              = 0;          # Should help message be printed to terminal?
my $useme               = 0;          # Should usage message be printed to terminal?
my $config_file_present = 0;
my $output_filename     = "";
my $progname            = "";

# Set program name according to OS. Assumes Windows users will use the .exe version of Perkins.
if ( $^O eq "MSWin32" ) {
    $progname = "perkins.exe";
}
elsif ( $^O eq "linux" ) {
    $progname = "perkins.pl";
}
elsif ( $^O eq "darwin" ) {
    $progname = "perkins.pl";
}
else {
    die "Unsupported operating system: $^O\n";
}

############################################################################
#            DECLARE VARIABLES THAT REQUIRE A (DEFAULT) VALUE              #
#  DON'T CHANGE ANYTHING HERE UNLESS YOU ARE REWRITING THE ENTIRE PROGRAM  #
############################################################################
my $accent                    = "";
my $acute_consonants          = "(b|ʧ|d|ʤ|ʝ|f|ɡ|j|k|l|m|ɲ|p|ɾ|r|ʂ|t|w|x|y|z)";
my $acute_consonants_except_j = "(b|ʧ|d|ʤ|ʝ|f|ɡ|k|l|m|ɲ|p|ɾ|r|ʂ|t|w|x|y|z)";
my $all_consonants            = "(b|ʧ|d|ʤ|ʝ|f|ɡ|j|k|l|m|ɲ|n|p|ɾ|r|s|ʂ|t|w|x|y|z)";
my $all_consonants_but_glides = "(b|ʧ|d|ʤ|ʝ|f|ɡ|k|l|m|ɲ|n|p|ɾ|r|s|ʂ|t|x|y|z)";
my $non_liquids               = "(b|ʧ|d|ʤ|ʝ|f|ɡ|j|k|m|ɲ|n|p|s|ʂ|t|w|x|y|z)";
my $orthog_epenth_e_cons      = "(b|c|d|f|g|j|k|l|m|n|p|q|r|s|t|v|x|y|z)";
my $stressed_vowels           = "(á|é|í|ó|ú)";
my $unstressed_vowels         = "(a|e|i|o|u)";
my $all_vowels                = "(a|e|i|o|u|á|é|í|ó|ú)";
my $strong_vowels             = "(a|e|o)";
my $weak_vowels               = "(i|u)";

# For sentence-level syllabification
my $all_consonants_diacr = "(b|ʧ|t͡ʃ|t̠͡ʃ|d|d̪|ʤ|d͡ʒ|d̠͡ʒ|ʝ|f|ɡ|j|k|l|m|ɲ|n|p|ɾ|r|s|ʂ|t|t̪|tɾ|t̪ɾ|t͡ɾ|t̪͡ɾ|w|x|y|z)";
my $all_vowels_diacr     = "(a|e|i|o|u|á|é|í|ó|ú|i̯|u̯)";

# The following are for the routine that replaces phonemes with C, V, N, L, G, etc.
my $misc_cons     = "(b|ʧ|d|ʤ|ʝ|f|ɡ|k|p|s|ʂ|t|x)";
my $nasals        = "(m|n|ɲ|ɱ|ŋ)";
# Includes ɱ/ŋ (--narrow's labiodental and velar nasal-place-
# assimilation outputs). n̪ (dental) is deliberately NOT added here --
# it's already correctly caught by the existing bare "n" alternative,
# confirmed directly: regex alternation matches at a position regardless
# of what follows, so "n̪" (n + dental diacritic) already matches plain
# "n" and gets classified "N" correctly, with the diacritic surviving
# afterward as a harmless cosmetic artifact -- adding "n̪" explicitly
# here would be redundant, not incorrect, but the existing entry already
# handles it.
my $liquids       = "(l)";
my $glides        = "(j|w)";
my $rhotics       = "(r|ɾ)";
my $vowels_glides = "(a|e|i|o|u|á|é|í|ó|ú|j|w)";

# The /tr/ group representation. "ʂ" is used to represent the phonemic status of "tr" in Chilean Spanish with a single symbol.
my $tr = "(ʂ)";

# The following are for the routine that replaces phonemes with MANNERS of articulation
# Includes ɟ/c (palatalized-velar stops from --narrow rule 9) --
# confirmed safe to add here since the CV/CVG/CVNLRG/voicing modes that
# also read these shared classes can never actually encounter these new
# symbols in the first place: that combination with --narrow is now a
# hard error (see the validation check near program start), so nothing
# here needs to account for how those modes would react to them.
my $plosives = "(b|d|ɡ|k|p|t|ɟ|c)";

# $nasals is declared above.
my $trills      = "(r)";
my $taps        = "(ɾ)";
# Includes v/ɣ/ç (plain fricatives from --narrow's spirantization
# and velar-palatalization rules).
# h is the glottal fricative of the interjections hmm (hm̩ː) and mmhm; ʃ
# the postalveolar fricative of sh (ʃ̩ː) and ch (t͡ʃʃ̩ː). In the modes that
# use these classes ch is the single character ʧ, so ʃ never matches part
# of it.
my $fricatives  = "(f|s|x|ʝ|v|ɣ|ç|h|ʃ)";
my $laterals    = "(l)";
my $affricates  = "(ʧ|ʤ|ʦ)";
# Includes ʋ/ð̞/ɣ̞/ʝ̞ (the "lowered"-diacritic, approximant-quality
# outputs of --narrow's intervocalic spirantization and palatalization
# rules). MUST be checked in opt_convert_phonemes_manners() BEFORE
# $fricatives, not after: ɣ̞ and ʝ̞ share their base character (ɣ, ʝ)
# with an existing bare entry already in $fricatives above, and since
# these are separate sequential substitutions (not one combined
# alternation), $fricatives running first would wrongly consume just
# the base character of ɣ̞/ʝ̞ as a plain fricative before $aproximants
# ever got a chance to see the full sequence -- confirmed by tracing
# through both regexes by hand, not assumed.
my $aproximants = "(j|w|ʋ|ð̞|ɣ̞|ʝ̞)";

# The following are for the routine that replaces phonemes with PLACES of articulation
my $bilabials     = "(b|m|p)";
# Includes v/ʋ/ɱ (labiodental outputs of --narrow's b-spirantization
# and nb->ɱv rule).
my $labiodentals  = "(f|v|ʋ|ɱ)";
# Includes ð̞ (dental fricative output of --narrow's d-spirantization)
# and n̪ (dental nasal from --narrow's nasal place assimilation). n̪ MUST
# be listed here, and $dentals MUST keep running before $alveolars below
# (already true in the existing substitution order) -- otherwise $alveolars'
# own bare "n" entry would wrongly catch n̪ as alveolar instead of dental,
# confirmed as a real bug found during stress-testing (place mode was
# showing "A̪" for a phoneme that should classify as dental "D").
my $dentals       = "(d|t|ð̞|n̪)";
my $alveolars     = "(n|ɾ|r|s|l|ʦ)";
my $postalveolars = "(ʧ|ʤ|ʃ)";
# Includes ɟ/ç/ʝ̞/c (--narrow's palatalized-velar outputs).
my $palatals      = "(j|ʝ|ɲ|ɟ|ç|ʝ̞|c)";
# Includes ɣ/ɣ̞/ŋ (--narrow's velar-fricative outputs and velar
# nasal from nasal place assimilation). Unlike the manner function, no
# ordering concern here: both ɣ and ɣ̞ map to the SAME place category
# (velar) either way, so it doesn't matter which one a bare "ɣ" entry
# happens to match first.
my $velars        = "(k|ɡ|x|ɣ|ɣ̞|ŋ)";
my $labiovelars   = "(w)";
# The h of hmm (hm̩ː) and mmhm.
my $glottals      = "(h)";
# Vowels, for the place output: front, central, back.
my $front_vowels   = "(i|e|í|é)";
my $central_vowels = "(a|á)";
my $back_vowels    = "(o|u|ó|ú)";

# The following are for the routine that replaces phonemes with VOICING
my $voiced   = "(a|e|i|o|u|á|é|í|ó|ú|b|d|ɡ|ʤ|ʝ|j|l|m|ɲ|n|ɾ|r|w)";
my $unvoiced = "(ʧ|f|k|p|s|ʂ|t|x|h|ʃ|ʦ)";

