     $utterance,             $item,                @uniquearray,         $next_char_syl_break, $sr_input_line,         @sr_array,
     $output_format,         $cfg_file_was_read,   $print_usage,         $current_numeral,     $numeral_converter_obj,
     $temp,                  $debug_message,       $user_message,        $eng,                 $esp,                   $long_pause_symbol
);

