#################################################################################

############################################################################
# Die with a red error message if an unknown option is given, rather than  #
# silently falling back to defaults.                                       #
############################################################################
local $SIG{__WARN__} = sub {
     my $msg = shift;
     if ( $msg =~ /^Unknown option/ ) {
          $msg =~ s/\s*\n*$//;    # strip trailing newline
          print STDERR safe_colored( "\nERROR: $msg\n", "bold red" );
          print STDERR safe_colored( "Run with -h for help.\n\n", "bold red" );
          exit 1;
     }
     warn $msg;    # pass through any other warnings unchanged
};

# Snapshot of all configurable variables at their DEFAULT values.
# Used at display time to determine which values came from which source.


############################################################################
#                                                                          #
#   MFA PHONOLOGICAL RULES (--mfa-rules)                                   #
#                                                                          #
#   Reproduces the allophony of the MFA Spanish dictionary, in its own      #
#   characters. Derived by measurement from the installed dictionary, not   #
#   from Spanish phonology -- the changelog entry that added --mfa-rules    #
#   gives the figures behind each rule.                                    #
#                                                                          #
#   --narrow is a different routine for a different purpose and is not      #
#   touched by any of this.                                                 #
#                                                                          #
############################################################################

# Exact characters, from a codepoint dump of the real dictionary.
our $MFA_BETA    = "\x{03B2}";           # GREEK small beta -- not Latin.
                                         # No longer a spirantisation
                                         # target. Chilean /b/ is labiodental.
our $MFA_VAPPROX = "\x{028B}";           # labiodental approximant
our $MFA_VFRIC   = "v";                  # labiodental fricative
our $MFA_ETH     = "\x{00F0}\x{031E}";       # APPROXIMANT eth (lowered)
our $MFA_ETH_FRIC = "\x{00F0}";               # plain fricative eth, kept for aliasing
our $MFA_GAMMA   = "\x{0263}\x{031E}";       # APPROXIMANT gamma (lowered)
our $MFA_GAMMA_FRIC = "\x{0263}";            # plain fricative gamma
our $MFA_G       = "\x{0261}";           # script g
our $MFA_TD      = "t\x{032A}";          # dental t
our $MFA_DD      = "d\x{032A}";          # dental d
our $MFA_ENG     = "\x{014B}";
our $MFA_MHOOK   = "\x{0271}";           # labiodental nasal
our $MFA_NPAL    = "\x{0272}";           # palatal nasal
our $MFA_CCED    = "\x{00E7}";           # precomposed
our $MFA_JSTROKE = "\x{025F}";
our $MFA_YFRIC   = "\x{029D}";
our $MFA_YAFF    = "d\x{0292}";           # d + ezh, POSTALVEOLAR, untied.
                                         # Formerly barred-dotless-j +
                                         # j-with-crossed-tail, the MFA Spanish
                                         # convention. This project trains its
                                         # own model and does not use it.
our $MFA_TESH    = "t\x{0283}";          # untied
our $MFA_LPAL    = "\x{028E}";
our $MFA_RTAP    = "\x{027E}";
our $MFA_TILDE   = "\x{0303}";           # combining -- vowels are DECOMPOSED

our @MFA_NASALS   = ( "m", "n", $MFA_ENG, $MFA_MHOOK, $MFA_NPAL );
our @MFA_LIQUIDS  = ( "l", "r", $MFA_RTAP, $MFA_LPAL );
# Palatalisation reaches across a RHOTIC only, never a lateral: measured, the
# dictionary keeps k before l in bicicleta, clerigo, nucleo.
our @MFA_RHOTICS  = ( "r", $MFA_RTAP );
# High front vocoids only. Measured: n palatalises before i and j but NOT
# before e -- erroneo, contemporaneo, colchones all keep plain n before e.
our @MFA_HIGHFRONT = ( "i", "i\x{0303}", "j" );
our @MFA_VOICED   = ( "b", $MFA_BETA, $MFA_DD, $MFA_ETH, $MFA_G, $MFA_GAMMA,
                      "m", "n", $MFA_ENG, $MFA_MHOOK, $MFA_NPAL,
                      "l", $MFA_LPAL, "r", $MFA_RTAP, "j", "w", "v" );
our @MFA_GLIDES   = ( "j", "w" );
our @MFA_FRONT    = ( "e", "i", "j", "e" . $MFA_TILDE, "i" . $MFA_TILDE );
our @MFA_VOWELS   = ( "a", "e", "i", "o", "u" );
our @MFA_LABIALS  = ( "p", "b", "m", $MFA_BETA );
# Labiodentals trigger the labiodental nasal, not plain m.
our @MFA_LABIODENTAL = ( "f", $MFA_VFRIC, $MFA_VAPPROX );
our @MFA_VELARS   = ( "k", $MFA_G, "x", $MFA_GAMMA, $MFA_ENG );
our @MFA_PALATALS = ( "c", $MFA_CCED, $MFA_JSTROKE, $MFA_TESH, $MFA_YAFF,
                      $MFA_YFRIC, $MFA_LPAL, $MFA_NPAL );

# Between two vowels, nasalised counted. Chilean /b/ takes the labiodental
# APPROXIMANT here and the labiodental FRICATIVE elsewhere.
sub _mfa_is_vowel {
     my ($x) = @_;
     return 0 unless defined $x;
     foreach my $v (@MFA_VOWELS) {
          return 1 if $x eq $v || $x eq $v . $MFA_TILDE;
     }
     return 0;
}
sub _mfa_intervocalic {
     my ($ref, $i) = @_;
     return 0 if $i == 0;
     return _mfa_is_vowel( $ref->[ $i - 1 ] ) && _mfa_is_vowel( $ref->[ $i + 1 ] );
}

sub _mfa_in { my ($x, @set) = @_; foreach my $y (@set) { return 1 if $x eq $y } return 0 }

# A front vocoid, reachable across at most one liquid. The transparency is
# measured: c precedes a rhotic in 38.5% of its occurrences, which a plain
# "before front vowels" rule does not predict.
sub _mfa_front_ahead {
     my ($ref, $i) = @_;
     for my $step ( 1, 2 ) {
          my $nx = $ref->[ $i + $step ];
          return 0 unless defined $nx;
          return 1 if _mfa_in( $nx, @MFA_FRONT );
          return 0 unless $step == 1 && _mfa_in( $nx, @MFA_RHOTICS );
     }
     return 0;
}

# A nasal in CODA position: followed by a consonant or the word edge. A vowel
# before an ONSET nasal does not nasalise -- abanico keeps a plain a.
sub _mfa_coda_nasal {
     my ($ref, $i) = @_;
     return 0 unless defined $ref->[$i] && _mfa_in( $ref->[$i], @MFA_NASALS );
     my $nx = $ref->[ $i + 1 ];
     return 1 unless defined $nx;                       # word edge
     return 0 if _mfa_in( $nx, @MFA_VOWELS );
     # A glide after the nasal means the nasal is an ONSET: nacimiento is
     # n a s i m j e-nasal ..., and the i before that m does NOT nasalise.
     return 0 if _mfa_in( $nx, @MFA_GLIDES );
     foreach my $v (@MFA_VOWELS) { return 0 if $nx eq $v . $MFA_TILDE }
     return 1;
}

sub mfa_phonological_rules {
     my ($pron) = @_;
     return $pron if $pron eq '';
     my @p = split( / /, $pron );

     # --- RULE 1: palatalise k and x before a front vocoid ----------------
     foreach my $i ( 0 .. $#p ) {
          next unless $p[$i] eq "k" || $p[$i] eq "x";
          next unless _mfa_front_ahead( \@p, $i );
          $p[$i] = ( $p[$i] eq "k" ) ? "c" : $MFA_CCED;
     }

     # RULE 1b REMOVED. Lateral palatalisation before a high front
     # vocoid is in the MFA dictionary (672 occurrences in a 10,000-word
     # comparison) and DOES NOT OCCUR IN CHILEAN SPANISH. Emitting it would
     # tell the aligner to look for a palatal lateral the speaker never
     # produced. Dictionary agreement is not the target; matching the audio is.

     # --- RULE 2: spirantisation ------------------------------------------
     # Stop after a pause or nasal; dental d also after a lateral.
     foreach my $i ( 0 .. $#p ) {
          my $is_b = ( $p[$i] eq "b" );
          my $is_d = ( $p[$i] eq $MFA_DD );
          my $is_g = ( $p[$i] eq $MFA_G );
          next unless $is_b || $is_d || $is_g;
          my $prev = ( $i == 0 ) ? undef : $p[ $i - 1 ];
          my $stop = 0;
          if ( !defined $prev )                        { $stop = 1 }
          elsif ( _mfa_in( $prev, @MFA_NASALS ) )       { $stop = 1 }
          elsif ( $is_d && $prev eq "l" )               { $stop = 1 }
          next if $stop;
          # /b/ lenites to a LABIODENTAL in Chilean, not a bilabial.
          # /d/ and /g/ unchanged -- their Chilean rows are not in yet.
          if ($is_b) {
               $p[$i] = _mfa_intervocalic( \@p, $i ) ? $MFA_VAPPROX : $MFA_VFRIC;
          }
          else { $p[$i] = $is_d ? $MFA_ETH : $MFA_GAMMA; }
     }

     # RULE 2b REMOVED. Coda obstruent lenition -- k to gamma
     # (411 occurrences), p to beta (88) -- is in the MFA dictionary and DOES
     # NOT OCCUR IN CHILEAN SPANISH. Chilean coda obstruents are weakened or
     # elided, not voiced to a continuant, and that weakening is variable, so
     # it belongs in rules.yaml as a variant rather than baked in here.

     # --- RULE 3: palatalise a surviving g stop ---------------------------
     foreach my $i ( 0 .. $#p ) {
          next unless $p[$i] eq $MFA_G;
          next unless _mfa_front_ahead( \@p, $i );
          $p[$i] = $MFA_JSTROKE;
     }

     # --- RULE 4: nasal place assimilation --------------------------------
     foreach my $i ( 0 .. $#p ) {
          next unless $p[$i] eq "n";
          my $nx = $p[ $i + 1 ];
          next unless defined $nx;
          if    ( _mfa_in( $nx, @MFA_LABIODENTAL ) )  { $p[$i] = $MFA_MHOOK }
          elsif ( _mfa_in( $nx, @MFA_LABIALS ) )      { $p[$i] = "m" }
          elsif ( _mfa_in( $nx, @MFA_PALATALS ) )     { $p[$i] = $MFA_NPAL }
          elsif ( _mfa_in( $nx, @MFA_HIGHFRONT ) )    { $p[$i] = $MFA_NPAL }
          elsif ( _mfa_in( $nx, @MFA_VELARS ) )       { $p[$i] = $MFA_ENG }
     }

     # RULE 5b REMOVED. s voicing before a voiced consonant (161
     # occurrences) is in the MFA dictionary and virtually never happens in
     # Chilean Spanish: syllable-final s is ASPIRATED to h or ELIDED. Both are
     # variable and sociolinguistically stratified, so neither is baked in
     # here -- they belong in rules.yaml, where MFA supplies both variants and
     # the acoustics choose. The model already has an h phone for exactly this.

     # --- RULE 6: yeismo -- affricate initially and after a nasal ---------
     foreach my $i ( 0 .. $#p ) {
          next unless $p[$i] eq $MFA_YFRIC;
          my $prev = ( $i == 0 ) ? undef : $p[ $i - 1 ];
          if ( !defined $prev || _mfa_in( $prev, @MFA_NASALS ) ) {
               $p[$i] = $MFA_YAFF;
          }
     }

     # --- RULE 5: vowel nasalisation before a CODA nasal ------------------
     foreach my $i ( 0 .. $#p ) {
          next unless _mfa_in( $p[$i], @MFA_VOWELS );
          next unless _mfa_coda_nasal( \@p, $i + 1 );
          $p[$i] = $p[$i] . $MFA_TILDE;                # DECOMPOSED, as the
     }                                                 # dictionary writes it

     return join( ' ', @p );
}


############################################################################
#                                                                          #
#   MFA PHONE-INVENTORY ENFORCEMENT                                        #
#                                                                          #
#   -mfa output may contain NOTHING outside the acoustic model's phone      #
#   inventory. Format validity is not enough: an out-of-inventory phone     #
#   parses perfectly and then fails to align, silently, because MFA has     #
#   never seen it.                                                          #
#                                                                          #
#   The inventory below is the REAL one, read from an installed            #
#   spanish_latin_america_mfa.dict with a codepoint dump on 260727 -- 43    #
#   phones. It is NOT the 33 on the model's published documentation page,   #
#   which omits ten of them.                                                #
#                                                                          #
#   Two distinct jobs here, and conflating them would be a mistake:         #
#                                                                          #
#   1. ENCODING ALIASES are silently rewritten. Precomposed nasalised       #
#      vowels, a decomposed c-cedilla, a tied affricate, ASCII g -- all the #
#      SAME phone written a different way. The dictionary's spelling wins,  #
#      byte for byte, because to MFA a one-codepoint difference is a        #
#      different phone.                                                     #
#                                                                          #
#   2. GENUINELY DIFFERENT PHONES are REJECTED, not mapped. The dental      #
#      nasal, the lowered fricatives, the v-with-hook -- these are --narrow #
#      symbols with no counterpart here. Mapping them would silently        #
#      convert one phone into another and hide the fact that the wrong mode #
#      is in use. The entry is dropped and reported with codepoints.        #
#                                                                          #
############################################################################

our %MFA_PHONESET = map { $_ => 1 } (
     "a", "a\x{0303}", "b", "c", "d\x{032A}", "e", "e\x{0303}", "f", "h",
     "i", "i\x{0303}", "j", "k", "l", "m", "n", "o", "o\x{0303}", "p", "r",
     "s", "t\x{0283}", "t\x{032A}", "u", "u\x{0303}", "v", "w", "x", "z",
     "\x{00E7}", "\x{00F0}", "\x{014B}", "\x{025F}", "d\x{0292}", "\x{0292}",
     "\x{0261}", "\x{0263}", "\x{0271}", "\x{0272}", "\x{027E}", "\x{0283}",
     "\x{028E}", "\x{029D}", "\x{03B2}", "\x{028B}",
     "\x{00F0}\x{031E}", "\x{0263}\x{031E}",
     "sil", "spn",
);

# Same phone, different bytes. Rewritten to the dictionary's own spelling.
our %MFA_PHONE_ALIAS = (
     "\x{00E3}"            => "a\x{0303}",   # precomposed nasalised vowels
     "\x{1EBD}"            => "e\x{0303}",
     "\x{0129}"            => "i\x{0303}",
     "\x{00F5}"            => "o\x{0303}",
     "\x{0169}"            => "u\x{0303}",
     "c\x{0327}"           => "\x{00E7}",    # decomposed c-cedilla
     "g"                   => "\x{0261}",    # ASCII g -> IPA script g
     "t\x{0361}\x{0283}"   => "t\x{0283}",   # tied affricates -> untied
     "t\x{035C}\x{0283}"   => "t\x{0283}",
     "\x{025F}\x{029D}"        => "d\x{0292}",   # MFA Spanish spelling -> ours
     "\x{025F}\x{0361}\x{029D}" => "d\x{0292}",
     "\x{025F}\x{035C}\x{029D}" => "d\x{0292}",
     "d\x{0361}\x{0292}"       => "d\x{0292}",   # tied -> untied
     "d\x{035C}\x{0292}"       => "d\x{0292}",
     "\x{02A4}"                 => "d\x{0292}",   # single-char DEZH
     "\x{02A7}"                 => "t\x{0283}",   # single-char TESH
);

# --mfa-phoneset FILE overrides the built-in inventory: one phone per line,
# blank lines and # comments ignored. Needed because this project trains its
# own acoustic model -- the inventory is no longer inherited from anyone, so
# it must not be compiled in.
sub mfa_load_phoneset {
     my ($path) = @_;
     open( my $fh, "<:encoding(UTF-8)", $path )
          or die "cannot read --mfa-phoneset $path: $!\n";
     my %new;
     while ( my $line = <$fh> ) {
          $line =~ s/#.*$//;
          $line =~ s/^\s+|\s+$//g;
          next if $line eq '';
          $new{$line} = 1;
     }
     close $fh;
     die "--mfa-phoneset $path contained no phones\n" unless keys %new;
     %MFA_PHONESET = ( %new, "sil" => 1, "spn" => 1 );
     return scalar( keys %new );
}

our $_mfa_phoneset_loaded = 0;
our $_mfa_dropped_phone   = 0;
our $_mfa_aliased         = 0;
our @_mfa_phone_examples  = ();

sub _mfa_cp { my ($x)=@_; return join(" + ", map { sprintf("U+%04X", ord($_)) } split(//, $x)) }

# Returns (pron, ok). ok=0 means an unknown phone -- caller drops the entry.
sub mfa_enforce_phoneset {
     my ($word, $pron) = @_;
     return ($pron, 1) if $pron eq '';
     my @out;
     foreach my $ph ( split( / /, $pron ) ) {
          next if $ph eq '';
          if ( exists $MFA_PHONE_ALIAS{$ph} ) {
               $ph = $MFA_PHONE_ALIAS{$ph};
               $_mfa_aliased++;
          }
          unless ( exists $MFA_PHONESET{$ph} ) {
               if ( scalar(@_mfa_phone_examples) < 10 ) {
                    push @_mfa_phone_examples,
                         sprintf('%s: "%s" (%s)', $word, $ph, _mfa_cp($ph));
               }
               return ($pron, 0);
          }
          push @out, $ph;
     }
     return ( join( ' ', @out ), 1 );
}

############################################################################
#                                                                          #
#   MFA DICTIONARY OUTPUT -- FORMAT AND PHONE-INVENTORY ENFORCEMENT        #
#   (format enforcement, then the phone guard)                             #
#                                                                          #
#   Every -mfa dictionary line goes through emit_mfa_entry() rather than    #
#   being printed directly, so the output file is guaranteed to satisfy     #
#   MFA's documented dictionary format rather than merely resembling it,    #
#   and guaranteed to carry a phone inventory MFA can actually model.       #
#                                                                          #
#   FORMAT (verified against MFA 3.x's own documentation):                 #
#   * EXACTLY ONE TAB between word and pronunciation -- a hard requirement  #
#     since MFA 2.0.5, not a convention. Any whitespace used to be          #
#     accepted; it no longer is, because phone sets like X-SAMPA use        #
#     digits as symbols and the parser could not otherwise tell a           #
#     two-column file from a probabilistic three-column one.                #
#   * Phones separated by non-tab whitespace. A pronunciation with no       #
#     internal spaces is read as ONE phone -- silently, not as an error,    #
#     which makes it the worst failure mode available here.                 #
#   * No tab inside the pronunciation; no whitespace inside the headword.   #
#                                                                          #
#   PHONE INVENTORY:                                                        #
#   * No stress mark and no acute accent may reach the pronunciation        #
#     column. MFA/Kaldi compare phone symbols as strings, so a stressed     #
#     vowel is a DIFFERENT PHONE from its unstressed counterpart, not the   #
#     same phone annotated. That splits each vowel's training data in two,  #
#     and against a pretrained model the stressed variants are not in its   #
#     inventory at all, so those entries cannot align. Same reasoning that  #
#     makes ARPAbet lexicons collapse AA0/AA1/AA2 to AA.                    #
#   * The ORTHOGRAPHIC column keeps its accents, deliberately. MFA matches  #
#     a word by the transcript's own orthography, so stripping them there   #
#     would stop real words being found.                                    #
#                                                                          #
#   Anything that cannot be made valid is DROPPED and counted, never        #
#   silently repaired into something plausible-but-wrong. Counts are        #
#   reported at end of run so nothing passes unnoticed.                     #
#                                                                          #
############################################################################

our %_mfa_seen                = ();
our $_mfa_written             = 0;
our $_mfa_dropped_empty_word  = 0;
our $_mfa_dropped_empty_pron  = 0;
our $_mfa_dropped_space_word  = 0;
our $_mfa_dropped_reserved    = 0;
our $_mfa_dropped_duplicate   = 0;
our $_mfa_stripped_stress     = 0;
our @_mfa_dropped_examples    = ();
our @_mfa_stress_examples     = ();

our %_MFA_RESERVED = map { $_ => 1 } ( "<unk>", "<eps>", "sil", "spn", "!sil" );

sub _mfa_note_drop {
     my ($reason, $word, $pron) = @_;
     if ( scalar(@_mfa_dropped_examples) < 10 ) {
          push @_mfa_dropped_examples, "$reason: \"$word\" -> \"$pron\"";
     }
}

############################################################################
# Remove stress marking from ONE phone token. Deliberately narrow: it takes #
# out the IPA primary/secondary stress marks and the acute accent only.     #
# It must NOT touch the phonetic diacritics --narrow depends on -- the      #
# dental bridge, the lowering tack, the nasalising tilde, the affricate tie #
# bar -- because those genuinely distinguish phones and MFA is right to     #
# treat them as separate symbols.                                          #
############################################################################
sub _mfa_strip_stress_from_phone {
     my ($ph) = @_;
     my $orig = $ph;
     $ph =~ s/\x{02C8}//g;                       # IPA primary stress
     $ph =~ s/\x{02CC}//g;                       # IPA secondary stress
     # Acute accent, precomposed and decomposed. Only the acute: Spanish
     # uses it for stress, and no phone in this project's inventory needs it.
     $ph =~ tr/\x{00E1}\x{00E9}\x{00ED}\x{00F3}\x{00FA}\x{00C1}\x{00C9}\x{00CD}\x{00D3}\x{00DA}/aeiouAEIOU/;
     $ph =~ s/\x{0301}//g;                       # combining acute
     return ($ph, $ph ne $orig);
}

sub emit_mfa_entry {
     my ($fh, $word, $pron) = @_;

     # The MFA dictionary's own allophony, in its own characters.
     # Applied here so every route into the output file goes through it.
     # Load a custom inventory once, on first use.
     if ( $mfa_phoneset_file ne '' && !$_mfa_phoneset_loaded ) {
          my $n = mfa_load_phoneset($mfa_phoneset_file);
          print STDERR "  phone inventory loaded from $mfa_phoneset_file "
                     . "($n phone(s)); the built-in list is not used.\n";
          $_mfa_phoneset_loaded = 1;
     }
     if ( $mfa_apply_rules ) { $pron = mfa_phonological_rules($pron); }

     # Nothing outside the model's phone inventory may be written.
     # Runs after the rules, so it validates what actually goes to the file.
     my $_ps_ok;
     ( $pron, $_ps_ok ) = mfa_enforce_phoneset( $word, $pron );
     unless ( $_ps_ok ) {
          $_mfa_dropped_phone++;
          return 0;
     }

     # --- normalise whitespace -------------------------------------------
     $word =~ s/\t/ /g;
     $pron =~ s/\t/ /g;
     $word =~ s/^\s+//;  $word =~ s/\s+$//;
     $pron =~ s/^\s+//;  $pron =~ s/\s+$//;
     $pron =~ s/\s+/ /g;

     # --- phone-inventory guard -------------------------------------------
     if ( $pron ne '' ) {
          my @phones = split( / /, $pron );
          my $changed_any = 0;
          foreach my $i ( 0 .. $#phones ) {
               my ($clean, $changed) = _mfa_strip_stress_from_phone( $phones[$i] );
               if ($changed) {
                    if ( scalar(@_mfa_stress_examples) < 10 ) {
                         push @_mfa_stress_examples, "$word: \"$phones[$i]\" -> \"$clean\"";
                    }
                    $phones[$i]  = $clean;
                    $changed_any = 1;
               }
          }
          if ($changed_any) {
               $_mfa_stripped_stress++;
               # A stripped token can come out empty (a lone stress mark
               # standing as its own token), so re-filter before rejoining.
               @phones = grep { $_ ne '' } @phones;
               $pron   = join( ' ', @phones );
          }
     }

     # --- reject what cannot be made valid --------------------------------
     if ( $word eq '' ) {
          $_mfa_dropped_empty_word++;
          _mfa_note_drop("empty headword", $word, $pron);
          return 0;
     }
     if ( $pron eq '' ) {
          $_mfa_dropped_empty_pron++;
          _mfa_note_drop("empty pronunciation", $word, $pron);
          return 0;
     }
     if ( $word =~ /\s/ ) {
          $_mfa_dropped_space_word++;
          _mfa_note_drop("whitespace in headword", $word, $pron);
          return 0;
     }
     if ( exists $_MFA_RESERVED{ lc($word) } ) {
          $_mfa_dropped_reserved++;
          _mfa_note_drop("reserved MFA token", $word, $pron);
          return 0;
     }

     # --- suppress exact duplicates ---------------------------------------
     my $key = "$word\t$pron";
     if ( exists $_mfa_seen{$key} ) {
          $_mfa_dropped_duplicate++;
          return 0;
     }
     $_mfa_seen{$key} = 1;

     print $fh "$word\t$pron\n";
     $_mfa_written++;
     return 1;
}

sub mfa_report_dropped {
     return if $silent_mode == 1;
     my $dropped = $_mfa_dropped_empty_word + $_mfa_dropped_empty_pron
                 + $_mfa_dropped_space_word + $_mfa_dropped_reserved;
     print STDERR "\nMFA dictionary: $_mfa_written entr" .
                  ( $_mfa_written == 1 ? "y" : "ies" ) . " written.\n";
     if ( $_mfa_dropped_duplicate > 0 ) {
          print STDERR "  $_mfa_dropped_duplicate exact duplicate line(s) suppressed.\n";
     }
     if ( $_mfa_stripped_stress > 0 ) {
          print STDERR "  WARNING: stress marking reached the phone column on " .
                       "$_mfa_stripped_stress entr" .
                       ( $_mfa_stripped_stress == 1 ? "y" : "ies" ) .
                       " and was stripped.\n";
          print STDERR "           -mfa mode should never produce this. Something " .
                       "has changed in the\n           metaconfig or in a mode " .
                       "interaction -- worth finding, not just tolerating.\n";
          foreach my $ex (@_mfa_stress_examples) {
               print STDERR "      e.g. $ex\n";
          }
     }
     if ( $_mfa_aliased > 0 ) {
          print STDERR "  $_mfa_aliased phone token(s) rewritten to the "
                     . "dictionary's own spelling (same phone, different bytes).\n";
     }
     if ( $_mfa_dropped_phone > 0 ) {
          print STDERR "  $_mfa_dropped_phone entr"
                     . ( $_mfa_dropped_phone == 1 ? "y" : "ies" )
                     . " DROPPED for a phone outside the model's inventory:\n";
          foreach my $ex (@_mfa_phone_examples) { print STDERR "      $ex\n" }
          print STDERR "    These parse fine and then fail to align. If they look\n"
                     . "    like --narrow symbols, --narrow is the wrong mode here;\n"
                     . "    use --mfa-rules instead.\n";
     }
     if ( $dropped > 0 ) {
          print STDERR "  $dropped entr" . ( $dropped == 1 ? "y" : "ies" ) .
                       " DROPPED as not representable in MFA format:\n";
          print STDERR "    $_mfa_dropped_empty_pron with an empty pronunciation\n"
               if $_mfa_dropped_empty_pron;
          print STDERR "    $_mfa_dropped_space_word with whitespace in the headword\n"
               if $_mfa_dropped_space_word;
          print STDERR "    $_mfa_dropped_empty_word with an empty headword\n"
               if $_mfa_dropped_empty_word;
          print STDERR "    $_mfa_dropped_reserved colliding with an MFA reserved token\n"
               if $_mfa_dropped_reserved;
          foreach my $ex (@_mfa_dropped_examples) {
               print STDERR "      e.g. $ex\n";
          }
     }
}

