     "mfa-phoneset=s"                              => \$mfa_phoneset_file,
     "mfa-rules!"                                  => \$mfa_apply_rules,
     "mfa!"                                        => \$mfa_format,
     "mfa-rt|mfa-running-text!"                    => \$mfa_force_running_text,  # Force -mfa to treat input as running text
     "mfa-wl|mfa-word-list!"                       => \$mfa_force_word_list,     # Force -mfa to treat input as one-word-per-line
     "nia|oa|ao!"                                  => \$non_ipa_apostrophes,
     "narrow|nt!"                                  => \$narrow_transcription,     # Apply narrow (allophonic) transcription rules
     "nyr|rae!"                                    => \$narrow_year_ranges,
     "och!"                                        => \$use_one_char_ch_symbol,
     "oye!"                                        => \$use_one_char_ye_symbol,
     "phon|fon|ph|IPA|AFI"                         => \$output_PHON,
     "phonword|pw!"                                => \$phonword_format,
     "place|pl|punto|p!"                           => \$output_place,
     "rt|tc|corpus!"                               => \$corpus_running_text,
     "sbs|sbu|spe|spo!"                            => \$syllabify_by_sentence,
     "silent-mode|silent|sil|sm!"                  => \$silent_mode,
     "syl-dots|sil-puntos|sd|sp!"                  => \$insert_syllable_dots,
     "syl-list|lista-sil|sl|ls!"                   => \$syllable_list,
     "syl-spaces|sil-esp|ss|se!"                   => \$syllable_dots_are_spaces,
     "times|times-colon|twc!"                      => \$times_with_colon,
     "urls|pu!"                                    => \$process_urls,
     "voicing|voice|v|sonoridad|son|s!"            => \$voicing,
     "vrt!"                                        => \$vrt_format,
     "word-list|lista-pal|wl|lp!"                  => \$word_list,
);

# Snapshot after CLI flags have been applied, before perkins.ini.
# Any var that differs from %_VAL_DEFAULT was set on the command line.
our %_SET_BY_INI = ();    # vars set by perkins.ini; populated in ini reader loop
our %_VAL_AFTER_CLI = ("debug" => $debug, "debug_syllab_sub" => $debug_syllab_sub, "debug_to_logfile" => $debug_to_logfile, "silent_mode" => $silent_mode, "batch_mode" => $batch_mode, "corpus_running_text" => $corpus_running_text, "syllable_list" => $syllable_list, "mfa_format" => $mfa_format, "phonword_format" => $phonword_format, "vrt_format" => $vrt_format, "output_PHON" => $output_PHON, "output_CV" => $output_CV, "output_CVG" => $output_CVG, "output_CVNLRG" => $output_CVNLRG, "output_manner" => $output_manner, "output_place" => $output_place, "voicing" => $voicing, "multichars" => $multichars, "tr_is_group" => $tr_is_group, "ch_dzh_retracted" => $ch_dzh_retracted, "use_ligatures" => $use_ligatures, "use_one_char_ch_symbol" => $use_one_char_ch_symbol, "ye_phoneme_is_fricative" => $ye_phoneme_is_fricative, "ye_phoneme_is_affricate" => $ye_phoneme_is_affricate, "use_one_char_ye_symbol" => $use_one_char_ye_symbol, "use_dental_diacr" => $use_dental_diacr, "add_epenthetic_g" => $add_epenthetic_g, "glides_with_diacritics" => $glides_with_diacritics, "non_syl_u_with_u_diacr" => $non_syl_u_with_u_diacr, "non_syl_i_with_i_diacr" => $non_syl_i_with_i_diacr, "ch_is_single_char" => $ch_is_single_char, "ch_is_retracted_with_ligature" => $ch_is_retracted_with_ligature, "ch_is_retracted_no_ligature" => $ch_is_retracted_no_ligature, "ch_not_retracted_with_ligature" => $ch_not_retracted_with_ligature, "ch_not_retracted_no_ligature" => $ch_not_retracted_no_ligature, "space_between_phonemes" => $space_between_phonemes, "word_plus_phonemes" => $word_plus_phonemes, "stress_using_tildes" => $stress_using_tildes, "no_stress_marks" => $no_stress_marks, "non_ipa_apostrophes" => $non_ipa_apostrophes, "narrow_transcription" => $narrow_transcription, "insert_syllable_dots" => $insert_syllable_dots, "split_at_syllables" => $split_at_syllables, "syllabify_by_sentence" => $syllabify_by_sentence, "syllable_dots_are_spaces" => $syllable_dots_are_spaces, "ipa_pause_symbols" => $ipa_pause_symbols, "ipa_long_pause_two_singles" => $ipa_long_pause_two_singles, "add_comma_pauses" => $add_comma_pauses, "add_colon_pauses" => $add_colon_pauses, "add_semicolon_pauses" => $add_semicolon_pauses, "add_sentence_breaks" => $add_sentence_breaks, "add_paragraph_breaks" => $add_paragraph_breaks, "add_ellipsis_pauses" => $add_ellipsis_pauses, "add_bracket_pauses" => $add_bracket_pauses, "add_paren_pauses" => $add_paren_pauses, "numerals_to_words" => $numerals_to_words, "num_symbol" => $num_symbol, "decimal_symbol" => $decimal_symbol, "narrow_year_ranges" => $narrow_year_ranges, "broad_year_ranges" => $broad_year_ranges, "bc_dates_included" => $bc_dates_included, "all_year_ranges" => $all_year_ranges, "times_with_colon" => $times_with_colon, "fix_umlauts" => $fix_umlauts, "fix_grave_accents" => $fix_grave_accents, "fix_circumflexes" => $fix_circumflexes, "fix_nasal_tildes" => $fix_nasal_tildes, "moneda" => $moneda, "rut_k_mode" => $rut_k_mode, "slash" => $slash, "process_urls" => $process_urls, "process_email" => $process_email, "name_for_v" => $name_for_v, "keep_paragraphs" => $keep_paragraphs, "vertical_output" => $vertical_output, "triple_vowels_to_double" => $triple_vowels_to_double, "kill_common_words" => $kill_common_words, "upper_case" => $upper_case);

############################################################################
#        PROCESS THE CONFIGURATION FILE (perkins.ini) IF IT EXISTS         #
#  If $use_config_file is true, then these options supersede the defaults  #
############################################################################

# Open config file if requested

if ( $use_config_file == 1 ) {

     if ( open( CONFIGFILE, '<:encoding(UTF-8)', "$config_filename" ) ) {

          $config_file_present = 1;

          # Set of variables that perkins.ini is allowed to set.
          # Using $$var = $value without this guard would let a
          # malicious (or typo-ridden) config file overwrite any
          # package global, including internal-only variables.
          my %_ALLOWED_CFG_VARS = map { $_ => 1 } qw(
               debug debug_syllab_sub debug_to_logfile silent_mode batch_mode
               corpus_running_text syllable_list mfa_format phonword_format vrt_format
               word_list coscach_mode
               output_PHON output_CV output_CVG output_CVNLRG output_manner output_place voicing
               multichars tr_is_group ch_dzh_retracted use_ligatures use_one_char_ch_symbol
               ye_phoneme_is_fricative ye_phoneme_is_affricate use_one_char_ye_symbol
               use_dental_diacr add_epenthetic_g
               glides_with_diacritics non_syl_u_with_u_diacr non_syl_i_with_i_diacr
               ch_is_single_char ch_is_retracted_with_ligature ch_is_retracted_no_ligature
               ch_not_retracted_with_ligature ch_not_retracted_no_ligature
               space_between_phonemes word_plus_phonemes
               stress_using_tildes no_stress_marks non_ipa_apostrophes
               narrow_transcription
               insert_syllable_dots split_at_syllables syllabify_by_sentence
               syllable_dots_are_spaces
               ipa_pause_symbols ipa_long_pause_two_singles
               add_comma_pauses add_colon_pauses add_semicolon_pauses add_sentence_breaks
               add_paragraph_breaks add_ellipsis_pauses add_bracket_pauses add_paren_pauses
               numerals_to_words num_symbol decimal_symbol
               narrow_year_ranges broad_year_ranges bc_dates_included all_year_ranges
               times_with_colon
               fix_umlauts fix_grave_accents fix_circumflexes fix_nasal_tildes
               moneda rut_k_mode slash process_urls process_email name_for_v
               keep_paragraphs vertical_output triple_vowels_to_double
               kill_common_words upper_case
          );

          while (<CONFIGFILE>) {

               chomp;
               s/#.*//;
               s/^\s+//;
               s/\s+$//;
               next unless length;

               my ( $var, $value ) = split( /\s*=\s*/, $_, 2 );

               $var =~ s/^\$//;   # Strip leading '$' if present in config file entry

               # Reject unknown variable names so a typo in perkins.ini
               # does not silently create a new package global (or worse,
               # overwrite an internal variable).
               unless ( exists $_ALLOWED_CFG_VARS{$var} ) {
                    print STDERR safe_colored(
                         "WARNING: $config_filename: unknown variable '$var' ignored.\n",
                         "bold yellow"
                    );
                    next;
               }

               {
                    # $var has already been validated against
                    # %_ALLOWED_CFG_VARS above, so this symbolic reference
                    # can only ever reach one of those known-safe package
                    # globals -- exactly the guarantee the whitelist check
                    # exists to provide. `use strict` (added later) forbids
                    # symbolic references by default; scope the exception
                    # as tightly as possible, to just this one assignment.
                    no strict 'refs';
                    $$var = $value;
               }
               $main::_SET_BY_INI{$var} = 1;   # record that ini set this var

               print STDOUT "Non-Default Option Set: $var = $value\n";
          }

          close(CONFIGFILE);
     }
     else {

          &config_file_failed;
     }
}

############################################################################
#          SET PROGRAM INTERFACE LANGUAGE IF BINARY SWITCHES USED          #
############################################################################
if ( $eng == 1 ) { $lang = "en" }
if ( $esp == 1 ) { $lang = "es" }

############################################################################
# NOTE: A "DEFINE LANGUAGE STRINGS FOR LOCALIZATION" step (assign_lang_str)  #
# used to be called here. It was an empty no-op stub -- never implemented   #
# and not wired to anything -- so it was removed. All bilingual (en/es)     #
# text in this program is handled inline via if($lang eq "es"){...}else{...}#
# branches, so no functionality is lost by removing it.                    #
############################################################################

############################################################################
#              IF USER NEEDS HELP, RUN HELP SUBROUTINE AND DIE             #
############################################################################
if ( $helpme == 1 ) {
     &print_help;
     exit;
}

############################################################################
#         IF  USER REQUESTS USAGE INFO, RUN THAT SUBROUTINE AND DIE        #
############################################################################
if ( $useme == 1 ) {
     &print_usage;
     exit;
}

# Lowercase any text provided with the -f (output format) switch           #
$output_format = lc($output_format);

############################################################################
# SET OPTIONS FOR DEBUGGING TO LOG FILE                                    #
############################################################################
if ( $debug_to_logfile == 1 ) {
     $debug = 1;
}

############################################################################
#                             VERIFY CLI OPTIONS                           #
#                         Only checks some of them.                        #
############################################################################

&verify_cli_options;

############################################################################
# OPEN INPUT FILE, CREATE LOG FILE                                         #
############################################################################
&open_input_and_log_files;

############################################################################
# -mfa: DECIDE WHETHER THIS INPUT IS RUNNING TEXT OR A ONE-WORD-PER-LINE   #
#       WORD LIST, BEFORE THE MAIN READ LOOP STARTS                       #
############################################################################
if ( $mfa_format == 1 ) {
     if ( $mfa_force_running_text == 1 ) {
          $mfa_input_is_running_text = 1;
     }
     elsif ( $mfa_force_word_list == 1 ) {
          $mfa_input_is_running_text = 0;
     }
     else {
          $mfa_input_is_running_text = detect_mfa_input_is_running_text( \*INPUTFILE );
     }
}


############################################################################
# Print bug log header, status messages, CLI info and cfg file status      #
# message                                                                  #
############################################################################
my $current_time = localtime();    # Get local time for log file
&print_header_CLI_status_msgs;

############################################################################
# ASSIGN DEFAULT OUTPUT FILENAME IF NECESSARY (.phnm extension)            #
############################################################################
if ( $output_filename eq "" ) {
     &assign_default_output_filename;
}

############################################################################
#              OPEN OUTPUT FILE - Output will be UTF-8                     #
############################################################################
&open_output_file;

############################################################################
# SNAPSHOT EXPLICIT SILENT/BATCH MODE STATE                                #
# Taken here -- after defaults, perkins.ini, and CLI flags have all been   #
# applied, but BEFORE forcibly_set_variables() runs. Some meta-config      #
# presets (--syl-list, --word-list, --rt/--corpus, --mfa, etc.) forcibly   #
# turn on silent mode (and, via it, batch mode) as a side effect, but that #
# should not by itself suppress the greeting -- only an EXPLICIT default,  #
# perkins.ini setting, or command-line flag should.                       #
############################################################################
our $explicit_silent_mode = $silent_mode;
our $explicit_batch_mode  = $batch_mode;

############################################################################
#                   PROCESS COMMAND LINE OPTIONS                           #
# If there are any, they supersede both the defaults and the .ini file     #
############################################################################
&process_command_line_options;

############################################################################
#         FORCIBLY SET VARIABLES THAT DEPEND ON OTHER VARIABLES            #
# This has to be done here, and not earlier, so as to receive any changed  #
# variable values from the config file or command line options.            #
############################################################################
&forcibly_set_variables;

############################################################################
#   VALIDATE: --narrow HAS NO EFFECT WITH CV/CVG/CVNLRG/VOICING OUTPUT     #
# These modes replace every phoneme with a single category letter         #
# (C/V, C/V/G, Vowel/Nasal/Liquid/Rhotic/Glide/Consonant, or voiced/       #
# voiceless) -- narrow_transcription()'s allophonic distinctions (e.g.    #
# spirantized b vs. stop b) collapse to the SAME category letter either   #
# way, so the flag combination can never change the output. Rather than  #
# silently produce output that looks fine but doesn't reflect --narrow    #
# at all, this is a hard error -- confirmed as a real, user-facing        #
# combination worth catching explicitly, not just documenting.            #
# Manner and place output are NOT included here: --narrow's new phonemes  #
# do change manner/place category in some real cases (e.g. a stop vs.    #
# fricative b lands in different manner categories), so that combination  #
# is meaningful and is made to work correctly instead of being blocked.   #
############################################################################
if ( $narrow_transcription == 1
     && ( $output_CV == 1 || $output_CVG == 1 || $output_CVNLRG == 1 || $voicing == 1 ) )
{
     my $bad_mode = $output_CV ? "CV" : $output_CVG ? "CVG" : $output_CVNLRG ? "CVNLRG" : "VOICING";
     if ( $lang eq "es" ) {
          $user_message = "ERROR: La combinación de --narrow con el formato $bad_mode no tiene ningún efecto -- "
               . "estos formatos reducen cada fonema a una sola letra de categoría, y las distinciones "
               . "alofónicas que aplica --narrow (p.ej. /b/ espirantizada vs. oclusiva) caen en la misma "
               . "categoría de todos modos. Use --manner o --place en su lugar, donde --narrow sí tiene efecto.";
     }
     else {
          $user_message = "ERROR: Combining --narrow with $bad_mode format has no effect -- these formats "
               . "reduce every phoneme to a single category letter, and the allophonic distinctions --narrow "
               . "applies (e.g. spirantized vs. stop /b/) collapse to the same category either way. "
               . "Use --manner or --place instead, where --narrow does have an effect.";
     }
     die "\n$user_message\n\n";
}

############################################################################
#                             CONSOLE GREETING                             #
# This is printed in normal (non-batch/non-silent) mode, but only if the   #
# debug to log file option is OFF. "Non-batch/non-silent" is judged by the #
# EXPLICIT snapshot above, not by $batch_mode/$silent_mode as they stand   #
# now -- a meta-config preset forcing silent mode on internally should not #
# by itself hide the greeting; only an explicit default/ini/CLI setting    #
# should.                                                                  #
############################################################################
if ( ( $explicit_batch_mode == 0 ) && ( $explicit_silent_mode == 0 ) && ( $debug_to_logfile == 0 ) ) {
     &print_console_greeting;
}

############################################################################
# Print message to log file if config file couldn't be read.               #
# Only done if debug is ON and debug to log file is ON.                    #
############################################################################
if ( ( $debug == 1 ) && ( $debug_to_logfile == 1 ) ) {
     print LOGFILE "\nDEBUG IO:  *WARINING* External config file couldn't be opened.";
     print LOGFILE "\nDEBUG IO:             Using defaults instead.";
}

sub start_of_program {

     # This is a dummy subroutine. Its only purpose is to generate an automatic
     # link in my IDE.
}

############################################################################
#                                                                          #
#                    BEGIN PROCESSING THE INPUT TEXT FILE                  #
#                                                                          #
############################################################################
while (<INPUTFILE>) {
     chomp;

     ############################################################################
     # MFA: CAPTURE THE ORIGINAL, UNPROCESSED INPUT LINE                        #
     # -mfa mode treats each input line as exactly one dictionary headword.     #
     # The line-level pipeline below (prelc_pass, lc, process_line) can turn a  #
     # single headword into several space-separated pseudo-words before it's   #
     # split into @word_array -- e.g. the ambiguous-Roman-letter spelling rule  #
     # turns "cd" into "se de", and institutional-acronym expansion turns      #
     # "afdd" into "asociación de familiares de detenidos desaparecidos". Once  #
     # @word_array is split, which original headword those pieces came from is #
     # lost. Capturing the untouched line here, before any of that runs, lets  #
     # -mfa re-key the eventual (possibly multi-word) transcription back onto  #
     # the ONE real headword instead of emitting one dictionary line per        #
     # resulting piece. See the -mfa output block below for how this is used.  #
     ############################################################################
     my $mfa_original_line = $_;

     ############################################################################
     # TOKEN MODE (--tokens): one input line = one sentence whose              #
     # tokens are separated by TABs; one output line with exactly as many      #
     # TAB-separated transcriptions. See transcribe_token_line().             #
     ############################################################################
     if ( $token_mode == 1 ) {
          my $token_output = transcribe_token_line($_);
          print OUTPUTFILE "$token_output\n";
          next;
     }

     # BUILT-IN PRONUNCIATIONS AND STAND-INS: whole tokens only, before
     # anything else can change them. See apply_builtin_exceptions().
     $_ = apply_builtin_exceptions($_);

     ########################################################################
     # PRE-LC PASS                                                           #
     # Case-sensitive tokens must be expanded BEFORE lc() destroys their    #
     # uppercase letters.  We produce all-lowercase Spanish words here so   #
     # they survive the lc() call below unchanged.                          #
     ########################################################################

     # ── PRE-LC PASS ──────────────────────────────────────────────────────
     # All case-sensitive token expansions (identifiers, era markers,
     # currency codes, Roman numerals) are handled in prelc_pass().
     # See the subroutine for the required processing order and rationale.
     $_ = prelc_pass($_);

     $input_line = lc;

     # ── LINE-LEVEL PIPELINE ──────────────────────────────────────────────
     # Era abbreviations, structured-token normalisation,
     # numeral expansion, symbol conversion, and all other line-level
     # preprocessing.  See process_line() for stage order and rationale.
     $input_line = process_line($input_line);

     ############################################################################
     #                             SPLIT LINES INTO WORDS                       #
     ############################################################################
     @word_array = split / /, $input_line;

     ############################################################################
     # BUFFERS FOR THIS LINE'S FINISHED WORDS                                   #
     # Words are not printed immediately. Instead they are collected here so   #
     # that fragments produced by the "-mente" splitting routine (which begin  #
     # with a leading "_") can be re-joined onto the previous word regardless  #
     # of whether output is horizontal (words on one line) or vertical (one    #
     # word per line, e.g. -mfa, -vo). $output_ortho stores the corresponding  #
     # orthographic form of each finished entry, for use by -mfa output.       #
     ############################################################################
     my @output_words = ();
     my @output_ortho  = ();

     foreach my $word (@word_array) {

          #print "\nBEF-CHANGE-¬-TO-SPACE :$word\n";           # AD-HOC DEBUG

          # Change ¬ to space.                                                       #
          $word =~ s/¬/ /g;

          #print "AFT-CHANGE-¬-TO-SPACE :$word\n";           # AD-HOC DEBUG

          ########################################################################
          # ERROR SENTINEL BYPASS                                                 #
          # Tokens that are error sentinels ([MalformedNumber], [InvalidDate],   #
          # etc.) must NOT be phonemicized. They are control tokens, not Spanish  #
          # words. Output them verbatim and skip all phonological processing.     #
          # [UtteranceBoundary] added here alongside the others -- inserted by    #
          # normalize_structured_tokens() in place of utterance-final punctuation #
          # (., ..., !, ?, :, ;), it must survive untouched until Stage 2         #
          # cleanup converts it to the real ‖ symbol.                            #
          ########################################################################
          if ($word =~ /^\[(?:MalformedNumber|InvalidDate|InvalidCurrency|InvalidFraction|UnknownToken|UtteranceBoundary)\]/) {
               push @output_words, $word;
               push @output_ortho,  $word;
               next;
          }

          # BUILT-IN PAUSES AND TRANSCRIPTIONS, placed by
          # apply_builtin_exceptions() as lowercase placeholders.
          my ( $builtin_out, $builtin_ortho ) = builtin_bypass($word);
          if ( defined $builtin_out ) {
               next if $builtin_out eq '';
               push @output_words, $builtin_out;
               push @output_ortho,  $builtin_ortho;
               next;
          }

          ############################################################################
          # SNAPSHOT THE ORTHOGRAPHIC FORM OF THE WORD                               #
          # Taken before any phonemic conversion, for use by -mfa output (which      #
          # needs the dictionary-form orthographic word alongside its transcription).#
          ############################################################################
          my $orthographic_word = $word;

          # Orthographic cleanup: kill-common-words test mode, vowel collapse,
          # letter spelling, pattern normalization.  See prepare_word_orthographic().
          $word = prepare_word_orthographic($word);

          # Full phonemic transcription pipeline: grapheme conversion, stress,
          # syllabification, optional symbol/format transforms.
          $word = transcribe_word($word);

          # Buffer this word (or join _mente continuation to previous word).
          buffer_word($word, $orthographic_word,
               \@output_words, \@output_ortho, $stress_using_tildes);

     }

     ############################################################################
     # OUTPUT EACH FINISHED WORD ON THIS LINE TO FILE                           #
     # format_output_word() handles phonword formatting; undef = skip.          #
     #                                                                          #
     # -mfa is handled separately, below, and NOT via format_output_word()'s    #
     # per-buffered-word loop. Two problems otherwise follow one input line     #
     # into a dictionary line-for-line:                                        #
     #                                                                          #
     #   1. EXPLOSION. When line-level preprocessing turns one headword into   #
     #      several space-separated pseudo-words (Roman-letter spelling,       #
     #      institutional-acronym expansion), each piece gets buffered as its  #
     #      own entry in @output_words, and the old per-word loop printed each #
     #      one on its own line -- so "cd" produced two orphaned-looking       #
     #      dictionary lines ("se\ts e" and "de\td e") instead of one entry    #
     #      ("cd\ts e d e"). Any tool reading this file one line per word      #
     #      silently gets extra, mis-keyed entries.                            #
     #                                                                          #
     #   2. SILENT DROP. format_output_word() returns undef for a word whose   #
     #      phoneme string comes out empty (e.g. a token made of characters    #
     #      outside the phoneme inventory). The old loop's `next unless        #
     #      defined` simply skipped it -- printing nothing at all for that     #
     #      input line, not even a placeholder. Combined with the one          #
     #      blank-line-per-input-line convention below, this collapsed two     #
     #      separator blank lines into one, silently shifting every           #
     #      subsequent line's word-to-entry correspondence in the file by one.  #
     #                                                                          #
     # Both are fixed the same way: -mfa emits exactly ONE line per INPUT      #
     # LINE (not per buffered sub-word), keyed on $mfa_original_line (captured #
     # before any line-level preprocessing ran -- see top of this loop), with  #
     # the phonemes of every buffered sub-word joined by a single space. If    #
     # every sub-word produced no phonemes at all -- or nothing was buffered   #
     # for this line -- the headword is still written, with an empty phoneme  #
     # field, so the entry is never silently dropped and stays traceable.      #
     ############################################################################
     if ( $mfa_format == 1 ) {

          if ( $mfa_input_is_running_text == 1 ) {

               ##########################################################################
               # RUNNING-TEXT MODE                                                     #
               # The input is real running text (prose), not a one-word-per-line word  #
               # list. Gluing an entire line into one "headword" (the word-list         #
               # behavior below) would be meaningless here -- a line of prose isn't a   #
               # single dictionary entry. Instead, use the SAME per-word breakdown      #
               # already produced by the loop above (@output_words / @output_ortho --   #
               # this already correctly handles numeral expansion, e.g. "1939" ->       #
               # "mil"/"novecientos"/"treinta"/"nueve" as four separate real words, and  #
               # acronym/Roman-letter expansion, since each expanded piece IS a          #
               # legitimate word deserving its own dictionary entry here -- unlike in    #
               # word-list mode, where the original input line's identity as a single   #
               # headword must be preserved). Each real word is added to a running,     #
               # file-wide, DEDUPLICATED dictionary (%mfa_running_text_dict), keeping    #
               # the first phoneme string seen for any given word. Nothing is printed    #
               # per-line here -- the whole accumulated dictionary is sorted and         #
               # printed once, after the main read loop finishes (see below it).         #
               ##########################################################################
               foreach my $i ( 0 .. $#output_words ) {
                    # The [UtteranceBoundary] sentinel (see normalize_structured_
                    # tokens() and the ERROR SENTINEL BYPASS) marks a pause, not a
                    # real word -- it has no place in a MFA dictionary entry and
                    # must be skipped here explicitly, since this mode never
                    # reaches the Stage-2 cleanup pass that converts it to ‖ for
                    # other output modes. Confirmed as a real leak during testing:
                    # without this skip, it was being treated as an ordinary word
                    # and garbled through build_mfa_phoneme_string().
                    next if $output_words[$i] eq '[UtteranceBoundary]';

                    my $orth = build_mfa_dict_key( $output_ortho[$i] );
                    next if $orth eq '';
                    next if exists $mfa_running_text_dict{$orth};    # keep first occurrence's transcription

                    my $phoneme_string = build_mfa_phoneme_string($output_words[$i]);
                    next unless defined $phoneme_string && $phoneme_string ne '';
                    # -mfa exits before the Stage-2 cleanup pass (see "MFA AND
                    # PHONWORD OUTPUT ARE ALREADY IN THEIR FINAL FORM" below),
                    # which is where narrow_transcription() normally runs --
                    # applied directly here instead so --narrow still has an
                    # effect in this mode. Real bug found and fixed: --narrow
                    # silently did nothing at all when combined with -mfa.
                    #
                    # ACKNOWLEDGED LIMITATION, not a bug: applied per-word,
                    # here, in isolation -- unlike the one-word-per-line
                    # branch below, this mode builds ONE independent,
                    # deduplicated dictionary entry PER WORD (meant to be
                    # reused for that word wherever it occurs later), so
                    # there is no next-word context available for a
                    # cross-word rule (e.g. nb -> ɱv) to ever see. Only the
                    # rules that don't need cross-word context (intervocalic/
                    # word-final spirantization, utterance-initial yeismo,
                    # within-word nasal assimilation and vowel nasalization)
                    # can have any effect in this specific mode.
                    if ( $narrow_transcription == 1 ) {
                         # -mfa's own per-phoneme spacing (when
                         # $space_between_phonemes==1) would otherwise be
                         # indistinguishable from a real word-boundary space
                         # -- replace with the \x01 placeholder first (see
                         # narrow_transcription()'s own $SEP definition),
                         # then convert back to a plain space afterward to
                         # match -mfa's expected output format.
                         ( my $placeheld = $phoneme_string ) =~ s/ /\x01/g;
                         $phoneme_string = narrow_transcription($placeheld);
                         $phoneme_string =~ s/\x01/ /g;
                    }

                    $mfa_running_text_dict{$orth} = $phoneme_string;
               }
          }
          else {

               ##########################################################################
               # ONE-WORD-PER-LINE MODE (original -mfa behavior, unchanged)             #
               ##########################################################################
               my @phone_groups = ();
               foreach my $i ( 0 .. $#output_words ) {
                    # The [UtteranceBoundary] sentinel must NOT simply be
                    # skipped here -- confirmed as a real bug found by
                    # further testing: skipping it silently deleted the
                    # boundary information before narrow_transcription() ever
                    # ran on the joined string, so a cross-word rule (e.g.
                    # nb->ɱv) could still wrongly fire straight across it
                    # ("un pan; beso" -> wrongly "ũ m p ã ɱ v e s o" instead
                    # of correctly blocking at the semicolon). Fixed by
                    # pushing the real ‖ character instead -- narrow_
                    # transcription() already correctly treats it as a hard
                    # boundary, exactly as it does everywhere else -- and
                    # stripping it back out of the final joined result
                    # afterward, since a literal pause symbol has no place
                    # in a finished MFA dictionary entry.
                    if ( $output_words[$i] eq '[UtteranceBoundary]' ) {
                         push @phone_groups, '‖';
                         next;
                    }

                    my $phoneme_string = build_mfa_phoneme_string($output_words[$i]);
                    if ( defined $phoneme_string && $phoneme_string ne '' ) {
                         # Same placeholder trick as the running-text branch
                         # above: -mfa's own per-phoneme spacing (when
                         # $space_between_phonemes==1) must not be confused
                         # with the real word-boundary space this array gets
                         # joined with below -- convert THIS word's internal
                         # spaces to \x01 now, before it's joined with any
                         # other word.
                         $phoneme_string =~ s/ /\x01/g if $narrow_transcription == 1;
                         push @phone_groups, $phoneme_string;
                    }
               }

               my $mfa_headword = build_mfa_dict_key( $mfa_original_line );

               # An input line with no letters at all (pure punctuation/whitespace
               # after cleanup) has no headword to key an entry on -- nothing is
               # written for it, same as before this fix. This should be rare
               # enough to be worth inspecting by hand if it ever happens.
               if ( $mfa_headword ne '' ) {
                    # -mfa exits before the Stage-2 cleanup pass where
                    # narrow_transcription() normally runs -- applied here
                    # instead, but on the FULLY JOINED multi-word string, not
                    # per-word: a real bug was found and fixed during testing
                    # where applying it to each word's phoneme string
                    # separately (before joining) meant cross-word rules like
                    # nb->ɱv could never see the word boundary at all, since
                    # each word was transformed in total isolation. The real
                    # (word-boundary) spaces from this join are what let
                    # cross-word rules fire; each word's own internal
                    # phoneme-spacing was already converted to the \x01
                    # placeholder above specifically so it isn't confused
                    # with a real word boundary here.
                    my $joined_phonemes = join( ' ', @phone_groups );
                    if ( $narrow_transcription == 1 ) {
                         $joined_phonemes = narrow_transcription($joined_phonemes);
                         $joined_phonemes =~ s/\x01/ /g;
                    }
                    # Strip the ‖ (and any stray double-space its removal
                    # leaves behind) from the FINAL result -- it did its job
                    # blocking cross-word rules above; it doesn't belong in
                    # the actual dictionary entry, narrowed or not (a plain,
                    # non-narrow MFA run never had ‖ in its output before
                    # this fix, and shouldn't gain one now).
                    $joined_phonemes =~ s/ ?‖ ?/ /g;
                    $joined_phonemes =~ s/^ +//;
                    $joined_phonemes =~ s/ +$//;
                    emit_mfa_entry(\*OUTPUTFILE, $mfa_headword, $joined_phonemes);
               }
          }
     }
     elsif ( $phonword_format == 1 && $word_list == 1 ) {

          ############################################################################
          # -phonword WITH -wl: EXACTLY ONE OUTPUT LINE PER INPUT LINE,             #
          # "input line verbatim<TAB>transcription", the transcriptions of all the #
          # pieces the line produced (14 -> catorce, PDI -> pe de i) joined by a   #
          # space, and an empty transcription rather than no line when nothing was #
          # produced. Lets a caller match output to input by line number.          #
          ############################################################################
          my @phons = grep { $_ ne '[UtteranceBoundary]' } @output_words;
          my $phon  = finalize_phon_string( join( ' ', @phons ) );
          ( my $orig = $mfa_original_line ) =~ s/\r$//;
          print OUTPUTFILE "$orig\t$phon\n";
          next;
     }
     else {
          # -phonword: each orthographic word gets back the capital letters it
          # had in the input ("Concepción", not "concepción"), as documented.
          # It used to come out in lower case, because the pipeline works in
          # lower case. See restore_ortho_case().
          if ( $phonword_format == 1 ) {
               restore_ortho_case( \@output_ortho, $mfa_original_line );
          }

          foreach my $i ( 0 .. $#output_words ) {
               # -phonword exits before Stage 2 (like -mfa), so it never
               # reaches the sentinel-to-‖ conversion there -- skip the
               # sentinel entirely here instead, since a phonword tier has
               # no meaningful "pause" entry. Every OTHER mode reached via
               # this same branch (default phonemic, CV/CVG/etc.) DOES
               # continue on to Stage 2 normally, where the sentinel is
               # already correctly converted -- so this skip must be
               # scoped to $phonword_format only, not applied generally.
               next if ( $phonword_format == 1 && $output_words[$i] eq '[UtteranceBoundary]' );

               # Nor any other pause symbol. -phonword switches the IPA pause
               # symbols off, so a full stop came through as the sentence
               # break ## and used to be printed as a word of its own,
               # "##<TAB>##".
               next if ( $phonword_format == 1 && $output_words[$i] =~ /^(?:[|‖]+|\(\.{1,3}\)|#{2,3})$/ );

               my $formatted = format_output_word($output_words[$i], $output_ortho[$i]);
               next unless defined $formatted;

               # -phonword, like -mfa, exits before the Stage-2 cleanup pass
               # where narrow_transcription() normally runs -- applied here
               # instead, but ONLY for -phonword, and ONLY to the phonemic
               # half of its "Ortho<TAB>transcription" output -- format_output_word()
               # keeps the original orthographic word (with real Spanish
               # letters like b/g/n that would otherwise be wrongly caught by
               # these rules) in the same string, before the tab. Default/
               # other modes reach Stage 2 normally and must NOT also get
               # this applied here, or it would run twice.
               # The WHOLE Stage-2 tail is applied here, not only the
               # narrow rules: output format (-f=CV and the rest), letter case and
               # syllable dots (-nosd, -ss). Formerly -phonword ignored all
               # three, because it exits before Stage 2. See finalize_phon_string().
               if ( $phonword_format == 1 ) {
                    my ($ortho_part, $phon_part) = split(/\t/, $formatted, 2);
                    if ( defined $phon_part ) {
                         $formatted = $ortho_part . "\t" . finalize_phon_string($phon_part);
                    }
               }

               if ( $vertical_output == 1 ) {
                    print OUTPUTFILE "$formatted\n";
               }
               else {
                    print OUTPUTFILE "$formatted ";
               }
          }
     }


     ############################################################################
     # PROCESS PARAGRAPH BREAKS                                                 #
     #                                                                          #
     # Skipped entirely for -mfa: this prints a pause marker and/or a trailing  #
     # blank line after EVERY input line, which made sense when one input line  #
     # could produce a variable number of output lines (the blank line marked   #
     # where that line's output ended). -mfa now always emits exactly one       #
     # self-contained dictionary line per input line (see above), so there is   #
     # nothing left for a separator to mark -- and "###" is a running-text      #
     # pause symbol that has no meaning inside a pronunciation dictionary.      #
     ############################################################################
     unless ( $mfa_format == 1 ) {

          # Add longest pause symbol ("###") if this option is chosen.          #
          if ( $add_paragraph_breaks == 1 ) { print OUTPUTFILE "###"; }

          # Add newlines at paragraph breaks if desired.                        #
          if ( $keep_paragraphs == 1 ) { print OUTPUTFILE "\n"; }
     }

}

############################################################################
# -mfa RUNNING-TEXT MODE: PRINT THE ACCUMULATED, DEDUPLICATED DICTIONARY   #
#                                                                          #
# Nothing was printed per-line for this mode inside the loop above -- the  #
# whole file had to be read first so words could be deduplicated across   #
# the entire input, not just within one line. Print the result now,       #
# alphabetically, same as a real word-list -mfa run would produce.        #
############################################################################
if ( $mfa_format == 1 && $mfa_input_is_running_text == 1 ) {
     foreach my $word ( sort keys %mfa_running_text_dict ) {
          emit_mfa_entry(\*OUTPUTFILE, $word, $mfa_running_text_dict{$word});
     }
}

#################################################################################
#                                                                               #
#                         CLOSE UP SHOP ON STAGE 1                              #
#                                                                               #
#################################################################################
close(INPUTFILE);
close(OUTPUTFILE);
if ( $mfa_format == 1 ) { mfa_report_dropped(); }



#################################################################################
#                                                                               #
#                                  STAGE 2                                      #
#                        PERFORM OUTPUT FILE CLEANING                           #
#                     (This should ALWAYS be activated)                         #
#################################################################################

#################################################################################
#                         Open output and temp files                            #
#################################################################################

###########################################################################
# WARN USER IF OUTPUT FILE CAN'T BE OPENED
###########################################################################
if ( $lang eq "es" ) {
     $user_message = "ADVERTENCIA: No fue posible abrir el archivo de salida \'$output_filename\' para lectura (input) y limpieza adicional.";
}
else {
     $user_message = "WARNING: The output file \'$output_filename\' could not be opened for reading and additional cleaning.";
}

###########################################################################
# MFA AND PHONWORD OUTPUT ARE ALREADY IN THEIR FINAL FORM. SKIP CLEANUP.
###########################################################################
if ( $mfa_format == 1 || $phonword_format == 1 || $token_mode == 1 ) {

     # -mfa output keeps the acoustic model's own spelling (see
     # nfc_output_file()); everything else is NFC.
     nfc_output_file($output_filename) unless $mfa_format == 1;

     if ( ( $explicit_batch_mode == 0 ) && ( $explicit_silent_mode == 0 ) ) {

          if ( $lang eq "es" ) {
               print STDOUT "\nLa transcripción se guardó en el archivo UTF-8 \"$output_filename\".\n";
          }
          else {
               print STDOUT "\nThe transcription was saved in the UTF-8 file \"$output_filename\".\n";
          }

     }

     exit;
}

###########################################################################
# OPEN THE OUTPUT FILE
###########################################################################
open( OUTPUTFILE, '<:encoding(UTF-8)', "$output_filename" )
  || die "\n\n$user_message\n\n";

#print STDOUT "\n >>> OFC: Opened the file $output_filename to read and then clean it.\n";             # NOTE DEBUGGING

# OPEN TEMP FILE. OUTPUT WILL BE UTF-8.
if ( $lang eq "es" ) {
     $user_message = "ADVERTENCIA: No fue posible crear el archivo temporal \($output_filename\).";
}
else {
     $user_message = "WARNING: The temporary file \'$output_filename\' could not be opened.";
}

open( TEMPFILE, '>:encoding(UTF-8)', "$output_filename\.cleaned" )
  || die "\n\n$user_message\n\n";

#print STDOUT " >>> OFC: Opened the file cleaned-$output_filename to write cleaned text into.\n";      # NOTE DEBUGGING

# BEGIN PROCESSING OUTPUT FILE
while (<OUTPUTFILE>) {
     chomp;

     # NOTE: case-adjustment (uc/lc) used to happen here, before cross-word
     # resyllabification. Moved to AFTER format conversion below, so that
     # word_level_syllab_adjust() (which matches literal lowercase IPA
     # phoneme characters) always sees real phonemes to work with,
     # regardless of output mode or eventual letter case.
     $input_line = $_;

     # ELIMINATE EXTRA WHITESPACE
     $input_line =~ s/\s(\s+)/$1/g;

     ############################################################################
     # CONVERT THE UtteranceBoundary SENTINEL TO THE REAL ‖ SYMBOL              #
     # normalize_structured_tokens() replaced utterance-final punctuation       #
     # (., ..., !, ?, :, ;) with this bracketed sentinel earlier in the        #
     # pipeline (see there, and the ERROR SENTINEL BYPASS, for why -- it      #
     # has to survive word-splitting and phonemicization untouched, which a   #
     # raw ‖ character couldn't safely do at that earlier stage). Converting  #
     # it here, right before clean_up_pauses() runs, lets that function's     #
     # existing pause-merging rules (adjacent | / ‖ collapsing, etc.) apply   #
     # to it exactly as they already do for any other pause marker.          #
     ############################################################################
     $input_line =~ s/\[UtteranceBoundary\]/‖/g;

     ############################################################################
     #                             CLEAN UP PAUSES                              #
     ############################################################################
     $input_line = &clean_up_pauses($input_line);

     # Print input line to debug log file, if desired.
     if ( $debug == 1 && $debug_to_logfile == 1 ) {
          print LOGFILE "\n==>$input_line";    #AD HOC DEBUG
     }

     # ELIMINATE UNDERSCORES (IN WORDS ENDING IN "-MENTE")
     $input_line =~ s/ _//g;
     $input_line =~ s/ _//g;

     #######################################################################
     #      PERFORM WORD-LEVEL SYLLABIFICATION ADJUSMENTS, IF DESIRED      #
     # This fixes things like "los hombres" = /los om.bres/, instead of    #
     # /lo.som.bres/. Runs BEFORE format conversion below (see the NOTE    #
     # in transcribe_word() for why this order matters) so this always    #
     # sees genuine IPA phonemes, in every output mode.                    #
     #######################################################################
     if ( $syllabify_by_sentence == 1 ) {

          #print STDOUT "\n\n$input_line"; # AD HOC DEBUG
          $input_line = word_level_syllab_adjust($input_line);
     }

     #######################################################################
     #      APPLY NARROW (ALLOPHONIC) TRANSCRIPTION RULES, IF DESIRED      #
     # Independent of $syllabify_by_sentence and of output mode -- works    #
     # the same way whether or not sentence-level syllabification is on.   #
     #######################################################################
     if ( $narrow_transcription == 1 ) {

          $input_line = narrow_transcription($input_line);
     }

     #######################################################################
     #                                                                     #
     #             OUTPUT FORMAT TRANSFORMATIONS (MOVED HERE)              #
     #                                                                     #
     #    Runs on the whole, already cross-word-resyllabified line, so    #
     #    C/V/N/L/R/G (etc.) letters correctly reflect any syllable       #
     #    boundary that shifted across a word boundary -- previously      #
     #    this ran per-word, before resyllabification, in                 #
     #    transcribe_word(), which silently prevented resyllabification   #
     #    from ever firing for these modes (its regex only matches        #
     #    literal IPA characters, not the converted letters).             #
     #######################################################################
     if ( $output_CV == 1 ) {
          $input_line = opt_convert_phonemes_cv($input_line);
     }
     elsif ( $output_CVG == 1 ) {
          $input_line = opt_convert_phonemes_cvg($input_line);
     }
     elsif ( $output_CVNLRG == 1 ) {
          $input_line = opt_convert_phonemes_cvnlrg($input_line);
     }
     elsif ( $output_manner == 1 ) {
          $input_line = opt_convert_phonemes_manners($input_line);
     }
     elsif ( $output_place == 1 ) {
          $input_line = opt_convert_phonemes_places($input_line);
     }
     elsif ( $voicing == 1 ) {
          $input_line = opt_convert_phonemes_voicing($input_line);
     }

     # ADJUST CASE AS REQUIRED (moved here -- see NOTE above)
     if ( $upper_case == 1 ) {
          $input_line = uc($input_line);
     }
     else {
          $input_line = lc($input_line);
     }
     $input_line = vowel_place_letters($input_line);

     ############################################################################
     #                   PROCESS SYLLABLE DOTS, IF DESIRED                      #
     ############################################################################

     # Convert syllable dots into spaces, if that option is selected       #
     if ( $syllable_dots_are_spaces == 1 ) {
          $input_line =~ s/\./ /g;
     }

     # ELIMINATE SYLLABLE DOTS IF THAT OPTION IS SELECTED                  #
     if ( $insert_syllable_dots == 0 ) {
          $input_line =~ s/\.//g;
     }

     #######################################################################
     # Print each cleaned-up line to the temporary file, in Unicode NFC    #
     # (see nfc_output_file()), with its own line break. The line break    #
     # used to come only from the paragraph pause (###), so with that      #
     # pause off (-noppp, -owl, -vrt, -sas) consecutive lines were glued    #
     # together, the last word of one onto the first word of the next.     #
     #######################################################################
     $input_line =~ s/\s+$//;
     print TEMPFILE Unicode::Normalize::NFC($input_line), "\n";

}

#################################################################################
#                        Close unneeded files                                   #
#################################################################################
close(OUTPUTFILE);
close(TEMPFILE);

###################################################################################
# Copy temp (cleaned) file on top of partially-finished file and delete temp file #
###################################################################################
copy( "$output_filename\.cleaned", "$output_filename" )
  or die " ***** Copying of cleaned file to output file failed! *****\n";

unlink("$output_filename\.cleaned");    # Deletes de file from disk

#################################################################################
# ONE WORD OR ONE SYLLABLE PER LINE (-owl, -vrt, -sas, -osl)                    #
#################################################################################
write_list_output($output_filename) if $list_mode ne '';

#################################################################################
# PRINT FINAL MESSAGE TELLING WHAT FILE THE TRANSCRIPTION IS IN                 #
#################################################################################
if ( ( $explicit_batch_mode == 0 ) && ( $explicit_silent_mode == 0 ) ) {

     if ( $lang eq "es" ) {
          $user_message = "La transcripción se guardó en el archivo UTF-8 \"$output_filename\".";
     }
     else {
          $user_message = "The transcription was saved in the UTF-8 file \"$output_filename\".";
     }

     print STDOUT "\n$user_message\n\n";
}

#################################################################################
#                                  Exit program                                 #
#################################################################################
exit;

#################################################################################
#                                                                               #
#                                                                               #
#                                                                               #
#                                                                               #
#                            SUBROUTINES LIVE HERE...                           #
#                                                                               #
#                                                                               #
#                                                                               #
#################################################################################

###############################################################################
#                SUBROUTINE: CONFIG FILE COULDN'T BE OPENED                   #
# NOTE: Must define lang strings HERE, and not in subroutine.                 #
###############################################################################
sub config_file_failed {

     if ( $lang eq "es" ) {
          $user_message = "ADVERTENCIA: No fue posible abrir el archivo de configuración ($config_filename).";
     }
     else {
          $user_message = "WARNING: The configuration file (\'$config_filename\') could not be opened.";
     }

     # Notify user that config file could NOT be opened.
     if ( ( $debug_to_logfile == 0 ) && ( $silent_mode == 0 ) ) {
          print STDOUT "\n\n$user_message\n";
     }
     elsif ( $debug_to_logfile == 1 ) {
          print LOGFILE "\n\n$user_message\n";
     }
     $config_file_present = 0;
}

###############################################################################
#                        SUBROUTINE: VERIFY CLI OPTIONS                       #
###############################################################################
sub verify_cli_options {

     # Make sure an input file was given, else die.
     if ( $input_filename eq "" ) {

          if ( $lang eq "es" ) {
               $user_message = "ERROR: Debes proporcionar el nombre del archivo a procesar. Esto se hace con la opción \'-i=input.txt\'";
          }
          else {
               $user_message = "ERROR: You must specify the name of the file to be processed with the -i flag (\'-i=input.txt\')";
          }

          &print_info_header;

          die "\n$user_message\n\n";
     }

     # TODO: Die when a non-existent option is provided

}

#################################################################################
#                        SUBROUTINE: COLOR HELPERS FOR HELP TEXT                #
#################################################################################
# Used only by print_help() below. Section headers get one color; the flag
# name(s) at the start of each option line get another -- but NOT the comma
# (and following space) that separates multiple aliases for the same option,
# which stays in the terminal's default color. See safe_colored() above for
# why this doesn't just call colored() directly.
sub color_header {
     my ($text) = @_;
     return safe_colored( $text, "bold blue" );
}

sub color_flags {
     my ($flags_str) = @_;
     return join( ", ", map {
          # If this flag token has a "=VALUE" placeholder (e.g. "--format=MODE",
          # "-sn=SYMBOL"), color the flag part green and the dummy/placeholder
          # value yellow, so it's visually obvious which part is literal and
          # which part the user is meant to replace.
          if ( /^([^=]+=)(.+)$/ ) {
               safe_colored( $1, "bold green" ) . safe_colored( $2, "yellow" );
          }
          else {
               safe_colored( $_, "bold green" );
          }
     } split( /,\s*/, $flags_str ) );
}

#################################################################################
#                        SUBROUTINE: HELP SECTION                               #
#################################################################################
sub print_help {

     &print_info_header;

     binmode STDOUT, ":utf8";
     if ( $lang eq "es" ) {

          print STDOUT "OPCIONES PRINCIPALES:";
          print STDOUT "\n " . color_flags("-i, --input=MIARCHIVO.TXT") . "     Especificar el archivo que se transcribirá.";
          print STDOUT "\n                               ESTE PARÁMETRO ES OBLIGATORIO.";
          print STDOUT "\n " . color_flags("-o, --output=MITRANSCR.TXT") . "    Especificar el archivo en el que se guardará";
          print STDOUT "\n                               la transcripción. Si no se especifica, se";
          print STDOUT "\n                               creará un archivo con el mismo nombre que el";
          print STDOUT "\n                               de entrada, pero con la extensión \".phnm\".";
          print STDOUT "\n";
          print STDOUT "\n NOTA: Si contienen espacios, los nombres de archivos deben ir entre comillas.";
          print STDOUT "\n";
          print STDOUT "\n " . color_flags("-h, --help") . "                    Ver la ayuda de Perkins.";
          print STDOUT "\n " . color_flags("-u, --uso") . "                     Ver ejemplos del uso de Perkins.";
          print STDOUT "\n " . color_flags("-cfg, -ini") . "                    Usar el archivo de configuración ($config_filename).";
          print STDOUT "\n " . color_flags("-nocfg, -noini") . "                NO usar el archivo de configuración.";
          print STDOUT "\n " . color_flags("-cf, --config-file=NOMBRE") . "     Usar NOMBRE en vez de \"perkins.ini\" como archivo";
          print STDOUT "\n                               de configuración (ej.: --config-file=corpora.ini).";
