          print STDOUT "\n      producir el efecto contrario: --nomulti, --nodebug, -notrg, --nod, etc.";
          print STDOUT "\n";
          print STDOUT "\n";
     }
     else {

          print STDOUT "MAIN OPTIONS:";
          print STDOUT "\n " . color_flags("-i, --input=MYFILE.TXT") . "        Specify the file to be processed. MANDATORY.";
