          print STDOUT "\n" . color_header("SPECIFIC PHONEME OPTIONS:");
          print STDOUT "\n " . color_flags("-multi, -mc") . "                   Use multi-character IPA symbols for some phonemes.";
          print STDOUT "\n " . color_flags("-och") . "                          Represent the \"ch\" phoneme as /ʧ/ regardless of any other setting";
          print STDOUT "\n " . color_flags("-tg") . "                           Treat /tr/ as a single phoneme - use ligature (adding -mc) or";
          print STDOUT "\n                               represent it as voiceless retroflex fricative /ʂ/ (adding -nomc).";
          print STDOUT "\n " . color_flags("-yf") . "                           Represent the \"ye\" phoneme as a fricative /ʝ/.";
          print STDOUT "\n " . color_flags("-ya") . "                           Represent the \"ye\" phoneme as an affricate /d͡ʒ/.";
          print STDOUT "\n " . color_flags("-oye") . "                          Represent the \"ye\" phoneme as /ʝ/ regardless of any other setting";
          print STDOUT "\n " . color_flags("-ar") . "                           Use the \"retracted\" diacritic in some affricates (e.g. t̠͡ʃ).";
          print STDOUT "\n " . color_flags("-lig") . "                          Use ligatures in /t͡ʃ/ and /d͡ʒ/. \'-nolig\' prevents their use.";
          print STDOUT "\n                               Must be used in conjunctin with the \'-mc\' switch!";
          print STDOUT "\n " . color_flags("-dd, --dent") . "                   Use dental diacritic with /t/ and /d/. Must use with \'-mc\'!";
          print STDOUT "\n " . color_flags("-aeg") . "                          Add epenthetic [g] before /w/ (e.g. <hueco> > [gweko].";
          print STDOUT "\n";
          print STDOUT "\n" . color_header("CH SHORTCUTS:");
          print STDOUT "\n " . color_flags("-chsc") . "                         CH shortcut: single character, e.g. ʧ. Overrides -mc/-ar/-lig";
          print STDOUT "\n                               for this phoneme only.";
          print STDOUT "\n " . color_flags("-chrl") . "                         CH shortcut: retracted, with ligature, e.g. t̠͡ʃ.";
          print STDOUT "\n " . color_flags("-chrnl") . "                        CH shortcut: retracted, no ligature, e.g. t̠ʃ.";
          print STDOUT "\n " . color_flags("-chnrl") . "                        CH shortcut: not retracted, with ligature, e.g. t͡ʃ.";
          print STDOUT "\n " . color_flags("-chnrnl") . "                       CH shortcut: not retracted, no ligature, e.g. tʃ.";
          print STDOUT "\n";
          print STDOUT "\n" . color_header("GLIDE OPTIONS:");
          print STDOUT "\n " . color_flags("-gd, --glides-dia") . "             Represent glides as vowel + the \"non-syllabic\" diacritic.";
          print STDOUT "\n " . color_flags("-nogd, --noglides-dia") . "         Represent glides as  /j/ and /w/.";
          print STDOUT "\n " . color_flags("-wv") . "                           Represent wau as u + the \"non-syllabic\" diacritic.";
          print STDOUT "\n " . color_flags("-yv") . "                           Represent yod as i + the \"non-syllabic\" diacritic.";
          print STDOUT "\n";
          print STDOUT "\n" . color_header("STRESS OPTIONS:");
          print STDOUT "\n " . color_flags("-st") . "                           Mark stress with tilde over vowel rather than IPA apostrophe.";
          print STDOUT "\n " . color_flags("-oa") . "                           Mark stress with orthographic apostrophe, rather than the IPA one.";
          print STDOUT "\n";
          print STDOUT "\n" . color_header("NARROW (ALLOPHONIC) TRANSCRIPTION:");
          print STDOUT "\n " . color_flags("-nt, --narrow") . "                  Apply Chilean Spanish narrow-transcription rules (b/d/g";
          print STDOUT "\n                               spirantization, yeismo affrication, nasal place";
          print STDOUT "\n                               assimilation, vowel nasalization) on top of the output of";
          print STDOUT "\n                               ANY transcription mode (-mfa, running text, -phonword,";
          print STDOUT "\n                               etc.). Only implements phonologically-conditioned rules;";
          print STDOUT "\n                               see the narrow-transcription-ruleset README for the full";
          print STDOUT "\n                               detail of every rule.";
          print STDOUT "\n";
          print STDOUT "\n" . color_header("SYLLABIFICATION OPTIONS:");
          print STDOUT "\n " . color_flags("-sd, --syl-dots") . "               Represent syllable divisions with periods.";
          print STDOUT "\n " . color_flags("-ss, --syl-spaces") . "             Represent syllable divisions with spaces.";
          print STDOUT "\n " . color_flags("-nosd") . "                         Do not separate syllables nor mark them in any way.";
          print STDOUT "\n " . color_flags("-sbu") . "                          Syllabify by utterance/sentence, not by word (\"los";
          print STDOUT "\n                               hombres\" becomes /lo.som.bres/ instead of /los om.bres/).";
          print STDOUT "\n " . color_flags("-nosbu") . "                        Syllabify by word, not by utterance/sentence (\"los";
          print STDOUT "\n                               hombres\" > /los om.bres/ instead of /lo.som.bres/).";
          print STDOUT "\n " . color_flags("-sas, --split-syls") . "            One syllable per line, without pauses or stress marks. The";
          print STDOUT "\n                               syllables are cut from running text (with -sbu, the";
          print STDOUT "\n                               default) or from each word on its own (with -nosbu).";
          print STDOUT "\n";
          print STDOUT "\n" . color_header("PAUSE AND GROUP OPTIONS:");
          print STDOUT "\n " . color_flags("-ip, --ipa-pauses") . "             Represent pauses with the IPA symbols | and  ||";
          print STDOUT "\n " . color_flags("-lp2") . "                          Represent long pauses with two short pause bars (||) instead of one";
          print STDOUT "\n                               long pause double bar (‖), which Praat can't display.";
          print STDOUT "\n " . color_flags("-cmp") . "                          Treat commas as pauses.";
          print STDOUT "\n " . color_flags("-clp") . "                          Treat colons as pauses.";
          print STDOUT "\n " . color_flags("-scp") . "                          Treat  semicolons as pauses.";
          print STDOUT "\n " . color_flags("-snp") . "                          Treat sentence breaks as pauses.";
          print STDOUT "\n " . color_flags("-ppp") . "                          Treat paragraph breaks as pauses.";
          print STDOUT "\n " . color_flags("-elp") . "                          Treat ellipses (...) as pauses.";
          print STDOUT "\n " . color_flags("-brp") . "                          Treat brackets [] as pauses.";
          print STDOUT "\n " . color_flags("-pnp") . "                          Treat parentheses as pauses.";
          print STDOUT "\n";
          print STDOUT "\n" . color_header("NUMBER PROCESSING OPTIONS:");
          print STDOUT "\n " . color_flags("-n2w") . "                          Convert numerals into word form (\"4\" > \"cuatro\").";
          print STDOUT "\n " . color_flags("-sn=SYMBOL") . "                    Replace numerals with the symbol specified here.";
          print STDOUT "\n " . color_flags("-nyr") . "                          Treat two groups of 4 digits separated by \"-\" as a range of";
          print STDOUT "\n                               years (\"1900-2000\" > \"1900 a 2000\", not \"1900 menos 2000\").";
          print STDOUT "\n " . color_flags("-byr") . "                          Treat two groups of 1 to 4 digits separated by \"-\" as a range of";
          print STDOUT "\n                               years (\"43-103\" > \"43 a 103\", not \"43 menos 103\").";
          print STDOUT "\n " . color_flags("-ayr") . "                          Treat ALL groups of 1 to 4 digits separated by a \"-\" as ranges of years.";
          print STDOUT "\n " . color_flags("-bcy") . "                          Also process BCE years.";
          print STDOUT "\n " . color_flags("-twc, --times-colon") . "           Process times (1-2 digits, a colon, two digits) as time";
          print STDOUT "\n                               expressions (e.g. \"14:30\"). On by default.";
          print STDOUT "\n " . color_flags("-dp, --decimal-period") . "         Use the period as the decimal point (12.35) and the comma";
          print STDOUT "\n                               as the thousands separator (1,500 = one thousand five hundred).";
          print STDOUT "\n " . color_flags("-dc, --decimal-comma") . "          Use the comma as the decimal point (12,35) and the period";
          print STDOUT "\n                               as the thousands separator (1.500 = one thousand five hundred). Default.";
          print STDOUT "\n";
          print STDOUT "\n" . color_header("SUBSTITUTION OPTIONS:");
          print STDOUT "\n " . color_flags("-cur=TEXT") . "                     Replace the \"\$\" symbol with the text specified here.";
          print STDOUT "\n " . color_flags("-lo=TEXT") . "                      Replace the \"/\" symbol with the text specified here.";
          print STDOUT "\n " . color_flags("-nsm, --no-stress-marks") . "       Do not indicate stress in any way.";
          print STDOUT "\n " . color_flags("-pu") . "                           Treat URLs as linguistic items. Otherwise, they're deleted";
          print STDOUT "\n " . color_flags("-pe") . "                           Treat e-mail addresses as linguistic items. Otherwise, they're";
          print STDOUT "\n                               deleted.";
          print STDOUT "\n";
          print STDOUT "\n" . color_header("PRESENTATION OPTIONS:");
          print STDOUT "\n " . color_flags("-owl") . "                          One word per line, without pauses (syllabified by word).";
          print STDOUT "\n " . color_flags("-osl") . "                          One syllable per line, without pauses (same as -sas).";
          print STDOUT "\n " . color_flags("-kp") . "                           Keep paragraph breaks. Otherwise, output will be a wall of text.";
          print STDOUT "\n " . color_flags("-kc") . "                           Eliminate common words (for testing purposes).";
          print STDOUT "\n " . color_flags("-tvd") . "                          Reduce 3+ identical consecutive vowels down to 2";
          print STDOUT "\n                               (e.g. \"nooo\" -> \"noo\"). On by default.";
          print STDOUT "\n";
          print STDOUT "\nNOTE: Most options that don't take an argument (i.e. binary options) can be reversed or negated by adding";
          print STDOUT "\n      \"no\" between the dash and the option itself (e.g. --nomulti, --nodebug, -notr, -nod).";
          print STDOUT "\n";
          print STDOUT "\n";
     }
}


#################################################################################
#                        SUBROUTINE: USAGE SECTION                              #
#################################################################################
sub print_usage {

     &print_info_header;

     binmode STDOUT, ":utf8";

     if ( $lang eq "es" ) {
          print STDOUT "                             GUÍA DE USO";
          print STDOUT "\n     Perkins ofrece gran cantidad de opciones para la transcripción.";
          print STDOUT "\n         A continuación, se presentan algunas de las más útiles";
          print STDOUT "\n";
          print STDOUT "\nNOTAS GENERALES:";
          print STDOUT "\n - Las opciones se pueden ingresar con \"-\" o \"--\", indistintamente.";
          print STDOUT "\n - El uso del símbolo \'=\' es optativo.";
          print STDOUT "\n - El orden de las opciones y de los nombres de archivos no tiene importancia.";
          print STDOUT "\n - Las opciones binarias pueden invertirse agregando \'no\' entre el guión";
          print STDOUT "\n     y la opción misma (e.g. \'-mc\' puede desactivarse con \'-nomc\').";
          print STDOUT "\n - El número de opciones que se pueden utilizar no tiene límite.";
          print STDOUT "\n - Si el nombre de un archivo contiene un espacio, debe ir entre comillas.";
          print STDOUT "\n - Si no se especifica un archivo de salida, se genera un nombre automáticamente";
          print STDOUT "\n     a partir del nombre del archivo fuente y según el modo de transcripción.";
          print STDOUT "\n";
          print STDOUT "\nSELECCIÓN DE UN MODO DE TRANSCRIPCIÓN:";
          print STDOUT "\n - El modo de la transcripción puede elegirse desde la línea de comandos de";
          print STDOUT "\n   dos maneras distintas: -f=MODO y -MODO.";
          print STDOUT "\n - Algunos modos válidos: F, CV, CVG, CVN, M, P, S. Para más información, ver abajo.";
          print STDOUT "\n";
          print STDOUT "\n                           EJEMPLOS DE USO:";
          print STDOUT "\n";
          print STDOUT "\nTEXTO FUENTE: En Concepción, se trata de aguantar la lluvia durante 5";
          print STDOUT "\n              meses del año. ¿Cachái?";
          print STDOUT "\n";
          print STDOUT "\n-------------------------------------------------------------------------------";
          print STDOUT "\nCOMANDO:      $progname -i=fuente.txt";
          print STDOUT "\n";
          print STDOUT "\nSALIDA:       en.kon.sep.ˈsjon | se.ˈt̪ɾa.t̪a.d̪e.a.ɡwan.ˈt̪aɾ.la.ˈʝu.bja.d̪u.ˈɾan.";
          print STDOUT "\n              t̪e.ˈsin.ko.ˈme.ses.d̪e.ˈla.ɲo ‖ ka.ˈt͡ʃaj";
          print STDOUT "\n";
          print STDOUT "\nDESCRIPCIÓN:  Opciones por defecto. Transcripción fonémica, silabificada por";
          print STDOUT "\n              enunciado (las sílabas cruzan los límites de palabra). Acento con";
          print STDOUT "\n              el apóstrofo AFI. Africadas con ligadura, dentales con";
          print STDOUT "\n              diacrítico, yod y wau como /j/ y /w/, el fonema \"ye\" como /ʝ/.";
          print STDOUT "\n              | es una pausa corta (una coma) y ‖ una larga (el fin de una";
          print STDOUT "\n              oración).";
          print STDOUT "\n-------------------------------------------------------------------------------";
          print STDOUT "\nCOMANDO:      $progname -i=fuente.txt -at";
          print STDOUT "\n";
          print STDOUT "\nSALIDA:       en.kon.sep.sjón | se.t̪ɾá.t̪a.d̪e.a.ɡwan.t̪áɾ.la.ʝú.bja.d̪u.ɾán.t̪e.";
          print STDOUT "\n              sín.ko.mé.ses.d̪e.lá.ɲo ‖ ka.t͡ʃáj";
          print STDOUT "\n";
          print STDOUT "\nDESCRIPCIÓN:  El acento se marca con tilde sobre la vocal tónica, en vez del";
          print STDOUT "\n              apóstrofo AFI.";
          print STDOUT "\n-------------------------------------------------------------------------------";
          print STDOUT "\nCOMANDO:      $progname -i=fuente.txt -nt";
          print STDOUT "\n";
          print STDOUT "\nSALIDA:       ẽŋ.kõn.sep.ˈsjõn | se.ˈt̪ɾa.t̪a.ð̞e.a.ɣ̞wãn̪.ˈt̪aɾ.la.ˈʝu.ʋja.ð̞u.ˈɾãn̪.";
          print STDOUT "\n              t̪e.ˈsĩŋ.kõ.ˈmẽ.ses.ð̞e.ˈlã.ɲõ ‖ ka.ˈt͡ʃaj";
          print STDOUT "\n";
          print STDOUT "\nDESCRIPCIÓN:  Transcripción estrecha del español de Chile, aplicada sobre el";
          print STDOUT "\n              modo actual (aquí, el fonémico). /b d g/ son oclusivas tras";
          print STDOUT "\n              pausa, tras nasal y, /d/, tras /l/; en los demás casos son";
          print STDOUT "\n              aproximantes o fricativas, también entre palabras: \"trata de\"";
          print STDOUT "\n              t̪ɾa.t̪a.ð̞e, \"lluvia\" ʝu.ʋja, \"aguantar\" a.ɣ̞wan, \"meses del\"";
          print STDOUT "\n              mẽ.ses.ð̞e. La /n/ toma el punto de articulación de la consonante";
          print STDOUT "\n              siguiente (\"cinco\" sĩŋ.kõ, \"aguantar\" ɣ̞wãn̪.t̪aɾ) y una vocal junto";
          print STDOUT "\n              a una consonante nasal se nasaliza. Cada regla se detalla en";
          print STDOUT "\n              perkins-narrow-transcription-ruleset_README.md.";
          print STDOUT "\n-------------------------------------------------------------------------------";
          print STDOUT "\nCOMANDO:      $progname -i=fuente.txt -ya";
          print STDOUT "\n";
          print STDOUT "\nSALIDA:       en.kon.sep.ˈsjon | se.ˈt̪ɾa.t̪a.d̪e.a.ɡwan.ˈt̪aɾ.la.ˈʤu.bja.d̪u.ˈɾan.";
          print STDOUT "\n              t̪e.ˈsin.ko.ˈme.ses.d̪e.ˈla.ɲo ‖ ka.ˈt͡ʃaj";
          print STDOUT "\n";
          print STDOUT "\nDESCRIPCIÓN:  El fonema \"ye\" es la africada /ʤ/. Con -nooye se escribe /d͡ʒ/,";
          print STDOUT "\n              con ligadura, como /t͡ʃ/.";
          print STDOUT "\n-------------------------------------------------------------------------------";
          print STDOUT "\nCOMANDO:      $progname -i=fuente.txt -ya -nooye -ar";
          print STDOUT "\n";
          print STDOUT "\nSALIDA:       en.kon.sep.ˈsjon | se.ˈt̪ɾa.t̪a.d̪e.a.ɡwan.ˈt̪aɾ.la.ˈd̠͡ʒu.bja.d̪u.ˈɾan.";
          print STDOUT "\n              t̪e.ˈsin.ko.ˈme.ses.d̪e.ˈla.ɲo ‖ ka.ˈt̠͡ʃaj";
          print STDOUT "\n";
          print STDOUT "\nDESCRIPCIÓN:  Las dos africadas llevan el diacrítico de retracción (/d̠͡ʒ/ y";
          print STDOUT "\n              /t̠͡ʃ/).";
          print STDOUT "\n-------------------------------------------------------------------------------";
          print STDOUT "\nCOMANDO:      $progname -i=fuente.txt -tg";
          print STDOUT "\n";
          print STDOUT "\nSALIDA:       en.kon.sep.ˈsjon | se.ˈt̪͡ɾa.t̪a.d̪e.a.ɡwan.ˈt̪aɾ.la.ˈʝu.bja.d̪u.ˈɾan.";
          print STDOUT "\n              t̪e.ˈsin.ko.ˈme.ses.d̪e.ˈla.ɲo ‖ ka.ˈt͡ʃaj";
          print STDOUT "\n";
          print STDOUT "\nDESCRIPCIÓN:  El grupo \"tr\" se trata como un solo fonema (/t̪͡ɾ/), como ocurre en";
          print STDOUT "\n              muchos hablantes chilenos.";
          print STDOUT "\n-------------------------------------------------------------------------------";
          print STDOUT "\nCOMANDO:      $progname -i=fuente.txt -tg -nomc";
          print STDOUT "\n";
          print STDOUT "\nSALIDA:       en.kon.sep.ˈsjon | se.ˈʂa.ta.de.a.ɡwan.ˈtaɾ.la.ˈʝu.bja.du.ˈɾan.";
          print STDOUT "\n              te.ˈsin.ko.ˈme.ses.de.ˈla.ɲo ‖ ka.ˈʧaj";
          print STDOUT "\n";
          print STDOUT "\nDESCRIPCIÓN:  Cada fonema se escribe con un solo carácter: /ʂ/ en vez de /t̪͡ɾ/,";
          print STDOUT "\n              /ʧ/ en vez de /t͡ʃ/, y /t/ y /d/ sin el diacrítico dental. Los";
          print STDOUT "\n              glides se configuran aparte, con -gd y -nogd.";
          print STDOUT "\n-------------------------------------------------------------------------------";
          print STDOUT "\nCOMANDO:      $progname -i=fuente.txt -gd";
          print STDOUT "\n";
          print STDOUT "\nSALIDA:       en.kon.sep.ˈsi̯on | se.ˈt̪ɾa.t̪a.d̪e.a.ɡu̯an.ˈt̪aɾ.la.ˈʝu.bi̯a.d̪u.ˈɾan.";
          print STDOUT "\n              t̪e.ˈsin.ko.ˈme.ses.d̪e.ˈla.ɲo ‖ ka.ˈt͡ʃai̯";
          print STDOUT "\n";
          print STDOUT "\nDESCRIPCIÓN:  Los glides se escriben como vocal + diacrítico no silábico (/i̯/,";
          print STDOUT "\n              /u̯/) en vez de /j/ y /w/.";
          print STDOUT "\n-------------------------------------------------------------------------------";
          print STDOUT "\nCOMANDO:      $progname -i=fuente.txt -nospe";
          print STDOUT "\n";
          print STDOUT "\nSALIDA:       en kon.sep.ˈsjon | se ˈt̪ɾa.t̪a d̪e a.ɡwan.ˈt̪aɾ la ˈʝu.bja d̪u.ˈɾan.";
          print STDOUT "\n              t̪e ˈsin.ko ˈme.ses d̪el ˈa.ɲo ‖ ka.ˈt͡ʃaj";
          print STDOUT "\n";
          print STDOUT "\nDESCRIPCIÓN:  Silabificación por palabra y no por enunciado: las sílabas no";
          print STDOUT "\n              cruzan los límites de palabra (\"del año\" d̪el ˈa.ɲo, y no";
          print STDOUT "\n              d̪e.ˈla.ɲo).";
          print STDOUT "\n-------------------------------------------------------------------------------";
          print STDOUT "\nCOMANDO:      $progname -i=fuente.txt -cv";
          print STDOUT "\n";
          print STDOUT "\nSALIDA:       VC.CVC.CVC.ˈCVVC | CV.ˈCCV.CV.CV.V.CVVC.ˈCVC.CV.ˈCV.CVV.CV.ˈCVC.";
          print STDOUT "\n              CV.ˈCVC.CV.ˈCV.CVC.CV.ˈCV.CV ‖ CV.ˈCVV";
          print STDOUT "\n";
          print STDOUT "\nDESCRIPCIÓN:  Consonantes (C) y vocales (V).";
          print STDOUT "\n-------------------------------------------------------------------------------";
          print STDOUT "\nCOMANDO:      $progname -i=fuente.txt -cvg";
          print STDOUT "\n";
          print STDOUT "\nSALIDA:       VC.CVC.CVC.ˈCGVC | CV.ˈCCV.CV.CV.V.CGVC.ˈCVC.CV.ˈCV.CGV.CV.ˈCVC.";
          print STDOUT "\n              CV.ˈCVC.CV.ˈCV.CVC.CV.ˈCV.CV ‖ CV.ˈCVG";
          print STDOUT "\n";
          print STDOUT "\nDESCRIPCIÓN:  Consonantes (C), vocales (V) y glides (G).";
          print STDOUT "\n-------------------------------------------------------------------------------";
          print STDOUT "\nCOMANDO:      $progname -i=fuente.txt -cvn";
          print STDOUT "\n";
          print STDOUT "\nSALIDA:       VN.CVN.CVC.ˈCGVN | CV.ˈCRV.CV.CV.V.CGVN.ˈCVR.LV.ˈCV.CGV.CV.ˈRVN.";
          print STDOUT "\n              CV.ˈCVN.CV.ˈNV.CVC.CV.ˈLV.NV ‖ CV.ˈCVG";
          print STDOUT "\n";
          print STDOUT "\nDESCRIPCIÓN:  N = nasal, L = lateral, R = rótica, G = glide, V = vocal, C = las";
          print STDOUT "\n              demás consonantes.";
          print STDOUT "\n-------------------------------------------------------------------------------";
          print STDOUT "\nCOMANDO:      $progname -i=fuente.txt -m";
          print STDOUT "\n";
          print STDOUT "\nSALIDA:       VN.PVN.FVP.ˈFXVN | FV.ˈPTV.PV.PV.V.PXVN.ˈPVT.LV.ˈFV.PXV.PV.ˈTVN.";
          print STDOUT "\n              PV.ˈFVN.PV.ˈNV.FVF.PV.ˈLV.NV ‖ PV.ˈAVX";
          print STDOUT "\n";
          print STDOUT "\nDESCRIPCIÓN:  Modos de articulación: P = oclusiva, N = nasal, R = vibrante";
          print STDOUT "\n              múltiple, T = vibrante simple, F = fricativa, L = lateral,";
          print STDOUT "\n              A = africada, X = aproximante, V = vocal.";
          print STDOUT "\n-------------------------------------------------------------------------------";
          print STDOUT "\nCOMANDO:      $progname -i=fuente.txt -p";
          print STDOUT "\n";
          print STDOUT "\nSALIDA:       fA.VbA.AfB.ˈAPbA | Af.ˈDAc.Dc.Df.c.VWcA.ˈDcA.Ac.ˈPb.BPc.Db.ˈAcA.";
          print STDOUT "\n              Df.ˈAfA.Vb.ˈBf.AfA.Df.ˈAc.Pb ‖ Vc.ˈTcP";
          print STDOUT "\n";
          print STDOUT "\nDESCRIPCIÓN:  Puntos de articulación: B = bilabial, L = labiodental,";
          print STDOUT "\n              D = dental, A = alveolar, T = postalveolar, P = palatal,";
          print STDOUT "\n              V = velar, W = labiovelar, G = glotal (la h de hmm); vocales en";
          print STDOUT "\n              minúscula: f = anterior (i, e), c = central (a), b = posterior";
          print STDOUT "\n              (o, u). \"tr\" es DA (dental y alveolar); con -tg, A.";
          print STDOUT "\n-------------------------------------------------------------------------------";
          print STDOUT "\nCOMANDO:      $progname -i=fuente.txt -voicing";
          print STDOUT "\n";
          print STDOUT "\nSALIDA:       SS.ASS.ASA.ˈASSS | AS.ˈASS.AS.SS.S.SSSS.ˈASS.SS.ˈSS.SSS.SS.ˈSSS.";
          print STDOUT "\n              AS.ˈASS.AS.ˈSS.ASA.SS.ˈSS.SS ‖ AS.ˈASS";
          print STDOUT "\n";
