          print STDOUT "\nCOMANDO:      $progname -i=fuente.txt -sas -nospe";
          print STDOUT "\n";
          print STDOUT "\nSALIDA:       en";
          print STDOUT "\n              kon";
          print STDOUT "\n              sep";
          print STDOUT "\n              sjon";
          print STDOUT "\n              se";
          print STDOUT "\n              (...)";
          print STDOUT "\n              ses";
          print STDOUT "\n              d̪el";
          print STDOUT "\n              a";
          print STDOUT "\n              ɲo";
          print STDOUT "\n              (...)";
