          print STDOUT "\nCOMMAND:      $progname -i=source.txt -nospe";
          print STDOUT "\n";
          print STDOUT "\nOUTPUT:       en kon.sep.ˈsjon | se ˈt̪ɾa.t̪a d̪e a.ɡwan.ˈt̪aɾ la ˈʝu.bja d̪u.ˈɾan.";
          print STDOUT "\n              t̪e ˈsin.ko ˈme.ses d̪el ˈa.ɲo ‖ ka.ˈt͡ʃaj";
