          print STDOUT "\n              kon.sep.ˈsjon";
          print STDOUT "\n              se";
          print STDOUT "\n              ˈt̪ɾa.t̪a";
          print STDOUT "\n              d̪e";
          print STDOUT "\n              a.ɡwan.ˈt̪aɾ";
          print STDOUT "\n              (...)";
          print STDOUT "\n";
