          print STDOUT "\n              are set (here, the defaults). Syllabifies by word.";
          print STDOUT "\n-------------------------------------------------------------------------------";
          print STDOUT "\nCOMMAND:      $progname -i=source.txt -sas";
          print STDOUT "\n";
          print STDOUT "\nOUTPUT:       en";
          print STDOUT "\n              kon";
          print STDOUT "\n              sep";
          print STDOUT "\n              sjon";
          print STDOUT "\n              se";
          print STDOUT "\n              (...)";
          print STDOUT "\n              ses";
          print STDOUT "\n              d̪e";
          print STDOUT "\n              la";
          print STDOUT "\n              ɲo";
          print STDOUT "\n              (...)";
          print STDOUT "\n";
          print STDOUT "\nDESCRIPTION:  One syllable per line, without pauses or stress marks, cut from";
          print STDOUT "\n              running text: with syllabification by utterance (the default),";
          print STDOUT "\n              \"del año\" gives d̪e, la, ɲo.";
          print STDOUT "\n-------------------------------------------------------------------------------";
          print STDOUT "\nCOMMAND:      $progname -i=source.txt -sas -nospe";
          print STDOUT "\n";
          print STDOUT "\nOUTPUT:       en";
          print STDOUT "\n              kon";
          print STDOUT "\n              sep";
          print STDOUT "\n              sjon";
          print STDOUT "\n              se";
          print STDOUT "\n              (...)";
          print STDOUT "\n              ses";
          print STDOUT "\n              d̪el";
          print STDOUT "\n              a";
          print STDOUT "\n              ɲo";
          print STDOUT "\n              (...)";
          print STDOUT "\n";
          print STDOUT "\nDESCRIPTION:  The syllables are cut from each word on its own: \"del año\" gives";
          print STDOUT "\n              d̪el, a, ɲo. -osl is the same as -sas.";
          print STDOUT "\n-------------------------------------------------------------------------------";
          print STDOUT "\nCOMMAND:      $progname -i=source.txt -syl-list";
          print STDOUT "\n";
          print STDOUT "\nOUTPUT:       en kon sep 'sjon | se 'ʂa ta de a ɡwan 'taɾ la 'ʝu bja du 'ɾan te";
          print STDOUT "\n              'sin ko 'me ses de 'la ɲo ‖ ka 'ʧaj";
          print STDOUT "\n";
          print STDOUT "\nDESCRIPTION:  For processing the text at the syllable level: syllables";
          print STDOUT "\n              separated by spaces, stress marked with an apostrophe, \"tr\" as";
          print STDOUT "\n              one phoneme.";
          print STDOUT "\n-------------------------------------------------------------------------------";
          print STDOUT "\nCOMMAND:      $progname -i=source.txt -coscach";
          print STDOUT "\n";
          print STDOUT "\nOUTPUT:       en kon sep sjón | se tɾá ta de a ɡwan táɾ la ʝú bja du ɾán te sín";
          print STDOUT "\n              ko mé ses de lá ɲo || ka tʃáj";
          print STDOUT "\n";
          print STDOUT "\nDESCRIPTION:  The conventions of the COSCACH corpus: stress marked with an";
          print STDOUT "\n              accent, syllables separated by spaces, the long pause as ||.";
          print STDOUT "\n-------------------------------------------------------------------------------";
          print STDOUT "\nCOMMAND:      $progname -i=source.txt -word-list";
          print STDOUT "\n";
          print STDOUT "\nOUTPUT:       en kon.sep.ˈsjon | se ˈtɾa.ta de a.ɡwan.ˈtaɾ la ˈʝu.bja du.ˈɾan.";
          print STDOUT "\n              te ˈsin.ko ˈme.ses del ˈa.ɲo ‖ ka.ˈʧaj";
          print STDOUT "\n";
          print STDOUT "\nDESCRIPTION:  For word lists in which each line is a word, not a sentence:";
          print STDOUT "\n              syllabifies by word, with one character per phoneme.";
          print STDOUT "\n-------------------------------------------------------------------------------";
          print STDOUT "\n";
          print STDOUT "\nFor more information, see program help: $progname -h";
          print STDOUT "\n\n";

     }
}

############################################################################
# SUBROUTINE: OPEN INPUT FILE, CREATE LOG FILE                             #
############################################################################
sub open_input_and_log_files {

     if ( $lang eq "es" ) {
          $user_message = "ERROR: No fue posible abrir el archivo de input \'$input_filename\'. Probablemente tipeaste mal su nombre.";
     }
     else {
          $user_message = "ERROR: The input file \'$input_filename\' could not be opened. Make sure you typed its name correctly.";
     }

     # Open INPUT FILE or die     # Input must be ISO-8859-1               #
     open( INPUTFILE, '<:encoding(UTF-8)', "$input_filename" )
       || die "\n$user_message\n\n";

     # Extract BASENAME of input file name                                 #
     $in_basename = $input_filename;
     $in_basename =~ s/(.+)\.(.+)/$1/;

     # Create DEBUG LOG file if required, now that we have the info to name it #
     if ( $debug_to_logfile == 1 ) {
          open( LOGFILE, '>:encoding(UTF-8)', "$in_basename.log" );
     }
}

############################################################################
#                                                                          #
# SUBROUTINE: DETECT WHETHER -mfa'S INPUT IS RUNNING TEXT OR AN EXISTING  #
#             ONE-WORD-PER-LINE WORD LIST                                 #
#                                                                          #
# Samples up to the first 500 non-blank lines of the (already-open) input #
# file handle and computes the average number of whitespace-separated    #
# tokens per line. A genuine one-word-per-line word list should average   #
# very close to 1. Real running text (sentences, paragraphs) will average #
# well above that -- typically 8-20+ words per line. 1.5 is a comfortably #
# wide margin: an ordinary word list with an occasional multi-word entry  #
# won't cross it, but real prose will, almost regardless of genre or      #
# sentence length.                                                        #
#                                                                          #
# Rewinds the file handle back to the beginning before returning, so the  #
# main read loop (which expects to start at the top of the file) is       #
# completely unaffected by this having run first.                        #
#                                                                          #
# Returns 1 (running text) or 0 (one-word-per-line).                      #
############################################################################
############################################################################
#                                                                          #
# SUBROUTINE: CLEAN AN ORTHOGRAPHIC WORD, PRESERVING INTERNAL APOSTROPHES  #
#                                                                          #
# Keeps letters and INTERNAL apostrophes (straight ' or curly ’) -- needed #
# to tell loanword/proper-noun pairs like "mcdonald's" and "mcdonalds"     #
# apart, which used to silently collide (in every output mode, not just    #
# -mfa, since this is called from buffer_word() -- see below) once the    #
# apostrophe was stripped. A LEADING or TRAILING apostrophe is still       #
# stripped, since those are virtually always a quotation mark around the   #
# word (e.g. 'hola') rather than part of the word itself. Does NOT change  #
# case -- callers that want a case-folded dictionary key (i.e. -mfa) do    #
# that themselves; other output modes (phonword, default) want the        #
# original capitalization preserved.                                      #
############################################################################
sub clean_orthographic_word {

     my $ortho = $_[0];

     $ortho =~ s/[^\p{L}'’]//g;    # Keep letters and apostrophes (straight or curly), drop everything else.
     $ortho =~ s/^['’]+//;         # Strip a leading apostrophe -- almost always a quotation mark.
     $ortho =~ s/['’]+$//;         # Same for a trailing one.

     return $ortho;
}

############################################################################
#                                                                          #
# SUBROUTINE: BUILD A -mfa DICTIONARY KEY FROM A RAW ORTHOGRAPHIC STRING   #
#                                                                          #
# Thin wrapper around clean_orthographic_word() that additionally         #
# lowercases, since a -mfa dictionary key should be case-insensitive      #
# (unlike the general orthographic form other output modes keep).         #
############################################################################
sub build_mfa_dict_key {

     return lc( clean_orthographic_word( $_[0] ) );
}

sub detect_mfa_input_is_running_text {

     my ($fh) = @_;

     my $lines_checked  = 0;
     my $nonblank_lines = 0;
     my $total_words    = 0;

     while ( my $line = <$fh> ) {
          last if $lines_checked >= 500;
          $lines_checked++;

          chomp $line;
          next if $line =~ /^\s*$/;

          $nonblank_lines++;
          my @tokens = split ' ', $line;
          $total_words += scalar(@tokens);
     }

     seek( $fh, 0, 0 );

     return 0 if $nonblank_lines == 0;    # Empty/blank input: don't change existing behavior.

     my $avg_words_per_line = $total_words / $nonblank_lines;

     return ( $avg_words_per_line > 1.5 ) ? 1 : 0;
}

############################################################################
#                                                                          #
# SUBROUTINE: PRINT DEBUG LOG HEADER, STATUS MESSAGES, CLI INFO AND        #
#             CFG FILE STATUS MESSAGES                                     #
#                                                                          #
############################################################################
sub print_header_CLI_status_msgs {

     # Print debugging log header                                               #
     if ( ( $debug == 1 ) && ( $debug_to_logfile == 1 ) ) {

          &print_info_header;

          print LOGFILE "\n|                        Perkins v$version                              |";

          print LOGFILE "\n|                          DEBUGGING LOG                               |";
          print LOGFILE "\n|                    $current_time                          |";
          print LOGFILE "\n ---------------------------------------------------------------------- ";
     }

     # Print status messages, either to console or log file.                    #
     if ( $debug == 1 ) {
          if ( $debug_to_logfile == 0 ) {
               print STDOUT "\nDEBUG CLI: \$input_filename =\t\t\t$input_filename";
               print STDOUT "\nDEBUG CLI: CLI-provided \$output_filename =\t$output_filename";
               print STDOUT "\nDEBUG CLI: CLI-provided \$output_format =\t$output_format";
          }
          if ( $debug_to_logfile == 1 ) {
               print LOGFILE "\nDEBUG CLI: \$input_filename\t\t\t\t=\t$input_filename";
               print LOGFILE "\nDEBUG CLI: CLI-provided \$output_filename\t=\t$output_filename";
               print LOGFILE "\nDEBUG CLI: CLI-provided \$output_format\t\t=\t$output_format";
          }
     }

     # Print info about CLI OPTIONS if desired, either to STDOUT or debug log   #
     if ( $debug == 1 ) {
          if ( $debug_to_logfile == 0 ) {
               print STDOUT "\nDEBUG CLI: \$in_basename =\t\t\t$in_basename";
          }
          elsif ( $debug_to_logfile == 1 ) {
               print LOGFILE "\nDEBUG CLI: \$in_basename\t\t\t\t\t=\t$in_basename";
          }
     }

     # Notify user that config file was read, either on STDOUT or in LOG FILE   #
     if ( $config_file_present == 1 ) {
          if ( ( $debug == 1 ) && ( $debug_to_logfile == 0 ) ) {
               print STDOUT "\n\n*** Configuration file ($config_filename) successfully read. ***\n\n";
          }
          elsif ( ( $debug == 1 ) && ( $debug_to_logfile == 1 ) ) {
               print LOGFILE "\n\n*** Configuration file ($config_filename) successfully read. ***\n";
          }
     }
}    # END SUBROUTINE: PRINT DEBUG LOG HEADER, STATUS MESSAGES, CLI INFO, ETC.

####################################################################################
# SUBROUTINE: ASSIGN DEFAULT OUTPUT FILENAME IF NECESSARY                          #
# V2: For ease of opening, this now postpends ".txt" to the old filenames (e.g.    #
#     "testfile.phnm" is now "testfile.phnm.txt". You might want to assign         #
#     different filetypes and icons to each of these to facilitate working w/ them #
####################################################################################
sub assign_default_output_filename {

     # -vrt (a word list): append ".vrt" to BASENAME, without ".txt".
     if ( $vrt_format == 1 ) {
          $in_basename     = "$in_basename.vrt";
          $output_filename = "$in_basename";
     }
     elsif ( $output_CV == 1 ) {
               $output_filename = "$in_basename.CV.txt";
          }
     elsif ( $output_CVG == 1 ) {
          $output_filename = "$in_basename.CVG.txt";
     }
     elsif ( $output_CVNLRG == 1 ) {
          $output_filename = "$in_basename.CVNLRG.txt";
     }
     elsif ( $output_manner == 1 ) {
          $output_filename = "$in_basename.MANNER.txt";
     }
     elsif ( $output_place == 1 ) {
          $output_filename = "$in_basename.PLACE.txt";
     }
     elsif ( $voicing == 1 ) {
          $output_filename = "$in_basename.VOICING.txt";
     }
     elsif ( $mfa_format == 1 ) {
          # .MFA.dict, not .MFA. MFA REJECTS a bare ".MFA" file --
          # it accepts only .dict, .txt, .yaml and .yml -- so the project's
          # own extension was the one extension MFA would not read, and
          # every dictionary needed a symlink before it could be used.
          # ".MFA.dict" keeps the convention visible and ends in something
          # MFA accepts. Only used when -o= is not given.
          $output_filename = "$in_basename.MFA.dict";
     }
     elsif ( $phonword_format == 1 ) {
          $output_filename = "$in_basename.PHONWORD";
     }
     elsif ( $syllable_list == 1 ) {
          $output_filename = "$in_basename.SYLLIST";
     }
     elsif ( $coscach_mode == 1 ) {
          $output_filename = "$in_basename.COSCACH";
     }
     elsif ( $corpus_running_text == 1 ) {
          $output_filename = "$in_basename.RUNTXT";
     }
     elsif ( $output_PHON == 1 ) {
          $output_filename = "$in_basename.PHNM.txt";
     }
     else {
          $output_filename = "$in_basename.PHNM.txt";
     }

     # The default name must never be the input file itself: with -vrt, an
     # input named "list.vrt" would otherwise be overwritten by its own word
     # list. "list.vrt" gives "list.out.vrt" instead.
     if ( $output_filename eq $input_filename ) {
          $output_filename =~ s/(\.[^.\/\\]+)$/.out$1/;
     }
}

     if ( $debug == 1 ) {
          if ( $debug_to_logfile == 0 ) {
               print STDOUT "\nDEBUG CLI: Default assigned OUTPUT filename =\t$output_filename";      # NOTE DEBUG IF REQUESTED
          }
          elsif ( $debug_to_logfile == 1 ) {
               print LOGFILE "\nDEBUG CLI: Default assigned OUTPUT filename\t=\t$output_filename";    # NOTE DEBUG DEBUGGING IF REQUESTED
          }
     }


############################################################################
#            SUBROUTINE: OPEN OUTPUT FILE - Output will be UTF-8           #
############################################################################
sub open_output_file {

     # Opening the output file empties it, so the output file must not be the
     # input file: that would erase the input before it is read.
     if ( -e $output_filename && -e $input_filename ) {
          my @o = stat($output_filename);
          my @i = stat($input_filename);
          my $same = $i[1]
            ? ( $o[0] == $i[0] && $o[1] == $i[1] )
            : ( lc( File::Spec->rel2abs($output_filename) ) eq lc( File::Spec->rel2abs($input_filename) ) );
          if ($same) {
               if ( $lang eq "es" ) {
                    print STDERR "\nERROR: El archivo de salida (-o=) es el mismo archivo de entrada (-i=). Elija otro nombre.\n\n";
               }
               else {
                    print STDERR "\nERROR: The output file (-o=) is the input file (-i=). Choose another name.\n\n";
               }
               exit 1;
          }
     }

     open( OUTPUTFILE, '>:encoding(UTF-8)', "$output_filename" );

     # Print any debug info that may be required
     if ( $debug == 1 ) {
          if ( $debug_to_logfile == 0 ) {
               print STDOUT "\nDEBUG CLI: Will use \$output_filename = \t\t$output_filename";       # NOTE IF DEBUGING REQUESTED
          }
          elsif ( $debug_to_logfile == 1 ) {
               print LOGFILE "\nDEBUG CLI: Will use \$output_filename\t\t=\t$output_filename\n";    # NOTE IF DEBUGGING REQUESTED
          }
     }
}

############################################################################
#               SUBROUTINE: PROCESS COMMAND LINE OPTIONS                   #
# If there are any, they supersede both the defaults and the .ini file     #
############################################################################
sub process_command_line_options {

     # Clear all default and config-file output format variables if any was given on the CLI #
     if ( $output_format ne "" ) {
          $output_CV     = 0;
          $output_CVG    = 0;
          $output_CVNLRG = 0;
          $output_manner = 0;
          $output_place  = 0;
          $voicing       = 0;
          $output_PHON   = 0;
     }

     # Set OUTPUT FORMAT (CV, CVG, etc.) VARIABLE, IF APPROPRIATE
     if ( $output_format eq "cv" ) {
          $output_CV = 1;
     }
     elsif ( $output_format eq "cvg" ) {
          $output_CVG = 1;
     }
     elsif ( ( $output_format eq "cvn" )
          || ( $output_format eq "cvnlrg" ) )
     {
          $output_CVNLRG = 1;
     }
     elsif ( ( $output_format eq "manner" )
          || ( $output_format eq "man" )
          || ( $output_format eq "modo" )
          || ( $output_format eq "m" ) )
     {
          $output_manner = 1;
     }
     elsif ( ( $output_format eq "place" )
          || ( $output_format eq "pl" )
          || ( $output_format eq "punto" )
          || ( $output_format eq "p" ) )
     {
          $output_place = 1;
     }
     elsif ( ( $output_format eq "voicing" )
          || ( $output_format eq "voice" )
          || ( $output_format eq "v" )
          || ( $output_format eq "sonoridad" )
          || ( $output_format eq "son" )
          || ( $output_format eq "s" ) )
     {
          $voicing = 1;
     }

     elsif ( ( $output_format eq "phon" )
          || ( $output_format eq "fon" )
          || ( $output_format eq "ph" )
          || ( $output_format eq "f" )
          || ( $output_format eq "IPA" )
          || ( $output_format eq "AFI" ) )
     {
          $output_PHON = 1;
     }

     if ( $debug == 1 ) {
          &print_cli_debug_info;
     }

}    #END SUBROUTINE

