DEBUG CLI: \$fix_nasal_tildes          =    $fix_nasal_tildes

DEBUG CLI: USER OPTIONS - SUBSTITUTIONS
DEBUG CLI: \$moneda                    =    $moneda
DEBUG CLI: \$slash                     =    $slash
DEBUG CLI: \$process_urls              =    $process_urls
DEBUG CLI: \$process_email             =    $process_email
DEBUG CLI: \$name_for_v                =    $name_for_v
DEBUG CLI: \$keep_paragraphs           =    $keep_paragraphs
DEBUG CLI: \$vertical_output           =    $vertical_output

DEBUG CLI: OPTIONS THAT USERS MAY *NOT* CONFIGURE
DEBUG CLI: \$cleanup_output_file       =    $cleanup_output_file
DEBUG CLI: \$no_separate_cleanup_file  =    $no_separate_cleanup_file

DEBUG CLI: OUTPUT: CLEANUP OPTIONS
DEBUG CLI: \$preclean_orthographic     =    $preclean_orthographic
DEBUG CLI: \$preclean_semiphonemic     =    $preclean_semiphonemic
DEBUG CLI: \$preclean_phonemic         =    $preclean_phonemic

DEBUG CLI: MISC
DEBUG CLI: \$upper_case                =    $upper_case
DEBUG CLI: \$kill_common_words         =    $kill_common_words

DEBUG CLI: \ INTERNAL VARIABLES THAT NEED INITIALIZED - DON'T CHANGE!
DEBUG CLI: \$helpme                    =    $helpme
DEBUG CLI: \$useme                     =    $useme
DEBUG CLI: \$config_file_present       =    $config_file_present
DEBUG CLI: \$output_filename           =    $output_filename
);

     if ( $debug_to_logfile == 0 ) {
          print STDOUT $debug_message;
     }
     elsif ( $debug_to_logfile == 1 ) {
          print LOGFILE $debug_message;
     }
}


############################################################################
# SUBROUTINE: FORCIBLY SET VARIABLES THAT DEPEND ON OTHER VARIABLES        #
# This has to be done here, and not earlier, so as to receive any changed  #
# variable values from the config file or command line options.            #
############################################################################
sub forcibly_set_variables {

     # Make sure values for the two "ye" phoneme variables don't contradict each other
     if ( $ye_phoneme_is_affricate == 1 ) {
          $ye_phoneme_is_fricative = 0;
     }
     else { $ye_phoneme_is_fricative = 1 }

     #######################################################################
     #                        METACONFIGURATIONS                           #
     #######################################################################

     ###################################
     # ALLOW ONLY ONE META-CONFIGURATION
     ###################################

     # Running text for corpora
     if ( $corpus_running_text == 1 ) {
          $syllable_list = 0;
          $vrt_format    = 0;
          $word_list     = 0;
          $mfa_format    = 0;
          $coscach_mode  = 0;
     }

     # Syllable list
     if ( $syllable_list == 1 ) {
          $corpus_running_text = 0;
          $vrt_format          = 0;
          $word_list           = 0;
          $mfa_format          = 0;
          $coscach_mode        = 0;
     }

     # Vertical text (VRT) format
     if ( $vrt_format == 1 ) {
          $corpus_running_text = 0;
          $syllable_list       = 0;
          $word_list           = 0;
          $mfa_format          = 0;
          $coscach_mode        = 0;
     }

     # Word list format
     if ( $word_list == 1 ) {
          $corpus_running_text = 0;
          $syllable_list       = 0;
          $vrt_format          = 0;
          $mfa_format          = 0;
          $coscach_mode        = 0;
     }

     # COSCACH mode
     if ( $coscach_mode == 1 ) {
          $corpus_running_text = 0;
          $syllable_list       = 0;
          $vrt_format          = 0;
          $word_list           = 0;
          $mfa_format          = 0;
     }

     # CORPUS OF RUNNING TEXT SETTINGS                                     #
     # Running text, syllabified at sentence level, accent using tildes,   #
     # single character per phoneme, output is phonemic transcription      #
     if ( $corpus_running_text == 1 ) {

          #$output_PHON             = 1; # Might have to disable this
          $multichars              = 0;
          $syllabify_by_sentence   = 1;
          $tr_is_group             = 0;
          $ye_phoneme_is_fricative = 1;
          $glides_with_diacritics  = 0;    # NEEDED ???
          $stress_using_tildes     = 1;
          $non_ipa_apostrophes     = 0;
          $insert_syllable_dots    = 1;
          $ipa_pause_symbols       = 1;
          $add_comma_pauses        = 1;
          $add_colon_pauses        = 1;
          $add_semicolon_pauses    = 1;
          $add_sentence_breaks     = 1;
          $add_paragraph_breaks    = 1;
          $add_ellipsis_pauses     = 1;
          $add_bracket_pauses      = 1;
          $add_paren_pauses        = 1;
          $numerals_to_words       = 1;
          $keep_paragraphs         = 1;
          $vertical_output         = 0;
          $kill_common_words       = 0;
          $silent_mode             = 1;
          $all_year_ranges         = 1;
          $times_with_colon         = 1;
     }

     # SYLLABLE LIST SETTINGS                                                      #
     # Doesn't specify transcription format, to allow different formats to be used.#
     # Syllabified at sentence level, running text, syllables separated by SPACE,  #
     # non-IPA apostrophe used,
     if ( $syllable_list == 1 ) {
          $multichars               = 0;
          $syllabify_by_sentence    = 1;
          $tr_is_group              = 1;
          $ye_phoneme_is_fricative  = 1;
          $glides_with_diacritics   = 0;    # NEEDED ???
          $stress_using_tildes      = 0;
          $non_ipa_apostrophes      = 1;
          $insert_syllable_dots     = 1;
          $syllable_dots_are_spaces = 1;
          $ipa_pause_symbols        = 1;
          $add_comma_pauses         = 1;
          $add_colon_pauses         = 1;
          $add_semicolon_pauses     = 1;
          $add_sentence_breaks      = 1;
          $add_paragraph_breaks     = 1;
          $add_ellipsis_pauses      = 1;
          $add_bracket_pauses       = 1;
          $add_paren_pauses         = 1;
          $numerals_to_words        = 1;
          $keep_paragraphs          = 1;
          $vertical_output          = 0;
          $kill_common_words        = 0;
          $silent_mode              = 1;
          $all_year_ranges          = 1;
          $times_with_colon         = 1;
     }

     # WORD LIST SETTINGS                                                            #
     # Doesn't specify transcription format, to allow different formats to be used.  #
     # Syllabified at word level, syllables separated by dot and words by a space.   #
     # Note that pauses are indeed processed (unless user indicates otherwise).      #
     # Also, note that this metaconfig sets relatively few variables.                #
     if ( $word_list == 1 ) {
          $multichars            = 0;
          $syllabify_by_sentence = 0;

          #$tr_is_group              = 1;
          #$ye_phoneme_is_fricative  = 1;
          #$glides_with_diacritics   = 0;
          #$stress_using_tildes      = 0;
          #$non_ipa_apostrophes      = 1;
          # -nosd on the command line is kept (it used to be overridden here).
          $insert_syllable_dots     = ( defined $_VAL_AFTER_CLI{insert_syllable_dots} && $_VAL_AFTER_CLI{insert_syllable_dots} == 0 ) ? 0 : 1;
          $syllable_dots_are_spaces = 0;
          $ipa_pause_symbols        = 1;
          $add_comma_pauses         = 1;
          $add_colon_pauses         = 1;
          $add_semicolon_pauses     = 1;
          $add_sentence_breaks      = 1;
          $add_paragraph_breaks     = 1;
          $add_ellipsis_pauses      = 1;
          $add_bracket_pauses       = 1;
          $add_paren_pauses         = 1;
          $numerals_to_words        = 1;
          $keep_paragraphs          = 1;
          $vertical_output          = 0;
          $kill_common_words        = 0;
          $silent_mode              = 1;
          $times_with_colon         = 1;
          #$all_year_ranges          = 1;
     }

     # MFA (GRAPHEME-TO-PHONEME) SETTINGS
     if ( $mfa_format == 1 ) {
          $output_PHON                  = 1;
          $output_CV                    = 0;
          $output_CVG                   = 0;
          $output_CVNLRG                = 0;
          $output_manner                = 0;
          $output_place                 = 0;
          $voicing                      = 0;
          $vrt_format                   = 0;

          $multichars                   = 1;
          $tr_is_group                  = 0;
          $ch_dzh_retracted             = 0;
          $use_ligatures                = 0;
          $ye_phoneme_is_fricative      = 1;
          $use_one_char_ch_symbol       = 0;
          $use_one_char_ye_symbol       = 1;
          $use_dental_diacr             = 1;
          $add_epenthetic_g             = 0;
          $glides_with_diacritics       = 0;

          $space_between_phonemes       = 1;
          $word_plus_phonemes           = 1;

          # Forced OFF (it was once forced ON). Stress
          # baked into phone identity needlessly fragments acoustic-
          # training data across stress variants of the same phone (the
          # same well-documented reason ARPAbet-based pipelines strip
          # AA0/AA1/AA2 down to AA before MFA-style alignment) -- -mfa
          # mode's whole purpose is producing a pronunciation dictionary
          # for exactly this kind of downstream use, so stress marking
          # is now off by default here specifically. Other output modes
          # (running-text phonemic transcription for TextGrid tiers,
          # etc.) are untouched -- $no_stress_marks is set independently
          # per mode, not globally.
          $no_stress_marks              = 1;
          $insert_syllable_dots         = 0;

          $ipa_pause_symbols            = 0;
          $ipa_long_pause_two_singles   = 0;
          $add_comma_pauses             = 0;
          $add_colon_pauses             = 0;
          $add_semicolon_pauses         = 0;
          $add_sentence_breaks          = 0;
          $add_paragraph_breaks         = 0;
          $add_ellipsis_pauses          = 0;
          $add_bracket_pauses           = 0;
          $add_paren_pauses             = 1;

          $fix_umlauts                  = 1;
          $fix_grave_accents            = 1;
          $fix_circumflexes             = 1;
          $fix_nasal_tildes             = 1;

          $numerals_to_words            = 1;
          $num_symbol                   = "·";
          $narrow_year_ranges           = 1;
          $broad_year_ranges            = 1;
          $bc_dates_included            = 1;
          $all_year_ranges              = 1;
          $times_with_colon             = 1;

          $moneda                       = "pésos";
          $slash                        = "eslách";
          $process_urls                 = 0;
          $process_email                = 0;
          $name_for_v                   = "becórta";

          $triple_vowels_to_double     = 1;
          $vertical_output              = 1;
     }

     # PHONWORD (PRAAT WORD/PHONWORD TIER) SETTINGS
     # Produces one word per line: orthographic form (capitalization and tildes
     # preserved) followed by a tab and the phonemic transcription with syllable
     # dots and stress markers intact.
     if ( $phonword_format == 1 ) {
          # An output format, -nosd and -nsm given on the command line
          # are kept. This block used to reset all of them, which is why
          # -pw silently ignored -f=CV, -nosd and the rest.
          unless ( $output_CV || $output_CVG || $output_CVNLRG || $output_manner || $output_place || $voicing ) {
               $output_PHON = 1;
          }
          $no_stress_marks      = $_VAL_AFTER_CLI{no_stress_marks}      ? 1 : 0;
          $insert_syllable_dots = ( defined $_VAL_AFTER_CLI{insert_syllable_dots} && $_VAL_AFTER_CLI{insert_syllable_dots} == 0 ) ? 0 : 1;

          $space_between_phonemes       = 0;    # No spaces between phonemes
          $word_plus_phonemes           = 0;

          $ipa_pause_symbols            = 0;
          $ipa_long_pause_two_singles   = 0;
          $add_comma_pauses             = 0;
          $add_colon_pauses             = 0;
          $add_semicolon_pauses         = 0;
          $add_sentence_breaks          = 0;
          $add_paragraph_breaks         = 0;
          $add_ellipsis_pauses          = 0;
          $add_bracket_pauses           = 0;
          $add_paren_pauses             = 1;

          $fix_umlauts                  = 1;
          $fix_grave_accents            = 1;
          $fix_circumflexes             = 1;
          $fix_nasal_tildes             = 1;

          $numerals_to_words            = 1;
          $all_year_ranges              = 1;
          $times_with_colon             = 1;

          $triple_vowels_to_double     = 1;
          $vertical_output              = 1;    # One word per line
     }


     # -vrt: WORD LIST SETTINGS                                                 #
     # Doesn't specify transcription format, to allow different ones to be used.#
     # One word per line (one syllable per line with -sas), syllabified by      #
     # word, stress using tildes. The list itself is made at the end, by        #
     # write_list_output(), like -owl and -sas.                                 #
     if ( $vrt_format == 1 ) {

          # $output_PHON = 1;
          $multichars               = 0;
          $syllabify_by_sentence    = 0;
          $tr_is_group              = 0;
          $ye_phoneme_is_fricative  = 1;
          $glides_with_diacritics   = 0;    # NEEDED ???
          $stress_using_tildes      = 1;
          $non_ipa_apostrophes      = 0;
          $insert_syllable_dots     = 1;
          $syllable_dots_are_spaces = 0;
          $ipa_pause_symbols        = 1;
          $add_comma_pauses         = 1;
          $add_colon_pauses         = 1;
          $add_semicolon_pauses     = 1;
          $add_sentence_breaks      = 1;
          $add_paragraph_breaks     = 1;
          $add_ellipsis_pauses      = 1;
          $add_bracket_pauses       = 1;
          $add_paren_pauses         = 1;
          $numerals_to_words        = 1;
          $keep_paragraphs          = 1;
          $vertical_output          = 1;
          $kill_common_words        = 0;
          $silent_mode              = 1;
          $all_year_ranges          = 1;
     }

     # COSCACH MODE SETTINGS
     if ( $coscach_mode == 1 ) {

          # $output_PHON = 1;
          $multichars               = 1;
          $syllabify_by_sentence    = 1;
          $tr_is_group              = 0;
          $ye_phoneme_is_fricative  = 1;
          $glides_with_diacritics   = 0;    # NEEDED ???
          $use_ligatures            = 0;
          $use_dental_diacr         = 0;
          $stress_using_tildes      = 1;
          $non_ipa_apostrophes      = 0;
          $insert_syllable_dots     = 1;
          $syllable_dots_are_spaces = 1;    # Not sure if I really like this in Coscach transcriptions
          $ipa_pause_symbols        = 1;
          $add_comma_pauses         = 1;
          $add_colon_pauses         = 1;
          $add_semicolon_pauses     = 1;
          $add_sentence_breaks      = 1;
          $add_paragraph_breaks     = 1;
          $add_ellipsis_pauses      = 1;
          $add_bracket_pauses       = 1;
          $add_paren_pauses         = 1;
          $numerals_to_words        = 1;
          $keep_paragraphs          = 1;
          $vertical_output          = 0;
          $kill_common_words        = 0;
          $silent_mode              = 0;
          $all_year_ranges          = 1;

          $ipa_long_pause_two_singles = 1;
     }

     # SPECIFIC CONFIGURATIONS

     # PROCESS NUMBER RANGES AS DATES
     if ( $all_year_ranges == 1 ) {
          $narrow_year_ranges = 1;
          $broad_year_ranges  = 1;
          $bc_dates_included  = 1;
     }

     # SET OPTIONS FOR USING NO STRESS MARKS
     if ( $no_stress_marks == 1 ) { $stress_using_tildes = 0 }

     # SET OPTIONS FOR SPLITTING AT SYLLABLES
     # A syllable list has no stress marks and needs the syllable dots to cut
     # at. Pauses stay on during the transcription, so that syllables are not
     # joined across a pause in running text; write_list_output() removes them.
     if ( $split_at_syllables == 1 ) {
          $insert_syllable_dots     = 1;
          $no_stress_marks          = 1;
          $stress_using_tildes      = 0;
          $non_ipa_apostrophes      = 0;
          $syllable_dots_are_spaces = 0;
     }

     # SET VALUES FOR MULTICHARS AND DIACRITICS IF A NON-PHONEMIC TRANSCRIPTION IS USED
     if (    $output_CV       == 1
          || $output_CVG      == 1
          || $output_CVNLRG   == 1
          || $output_manner   == 1
          || $output_place    == 1
          || $voicing         == 1 )
     {
          $multichars             = 0;
          $non_syl_u_with_u_diacr = 0;
          $non_syl_i_with_i_diacr = 0;

          $upper_case = 1;
     }

     # SET OPTIONS FOR VERTICAL OUTPUT
     if ( $vertical_output == 1 ) {
          $add_comma_pauses     = 0;
          $add_colon_pauses     = 0;
          $add_semicolon_pauses = 0;
          $add_sentence_breaks  = 0;
          $add_paragraph_breaks = 0;
          $add_ellipsis_pauses  = 0;
          $add_bracket_pauses   = 0;
          $add_paren_pauses     = 0;
     }

     # ONE WORD OR ONE SYLLABLE PER LINE (-owl, -vrt, -sas, -osl)
     # The transcription runs as ordinary running text, one line per input
     # line, so that every cleanup step of Stage 2 sees the words in context.
     # The list is cut from the finished file at the very end, by
     # write_list_output(). (Printing one word per line in Stage 1, as was once
     # done, lost every line break in Stage 2.) -mfa, -phonword and
     # -tok write their own one-entry-per-line formats and are not affected.
     # A word list is syllabified word by word, since sentence-level
     # syllabification joins the words with syllable dots. A syllable list is
     # cut from running words (sentence-level syllabification, the default) or
     # from single words (-nosbu, and the -vrt preset).
     if ( $mfa_format == 0 && $phonword_format == 0 && $token_mode == 0 ) {
          if ( $split_at_syllables == 1 ) {
               $list_mode = 'syllables';
          }
          elsif ( $vertical_output == 1 ) {
               $list_mode                = 'words';
               $syllabify_by_sentence    = 0;
               $syllable_dots_are_spaces = 0;
          }
          $vertical_output = 0 if $list_mode ne '';
     }

     # SET OPTIONS FOR SILENT MODE
     if ( $silent_mode == 1 ) {
          $batch_mode       = 1;
          $debug            = 0;
          $debug_syllab_sub = 0;
          $debug_to_logfile = 0;
     }

     # SET OPTIONS FOR GLIDES WITH/WITHOUT DIACRITICS
     if ( $glides_with_diacritics == 1 ) {
          $non_syl_u_with_u_diacr = 1;
          $non_syl_i_with_i_diacr = 1;
     }
     elsif ( $glides_with_diacritics == 0 ) {
          $non_syl_u_with_u_diacr = 0;
          $non_syl_i_with_i_diacr = 0;
     }

     # SET OPTIONS FOR NON-IPA APOSTROPHES
     if ( $non_ipa_apostrophes == 1 ) {
          $stress_using_tildes = 0;
     }

     # SET OPTIONS FOR SYLLABLES DOTS AS SPACES
     if ( $syllable_dots_are_spaces == 1 ) { $insert_syllable_dots = 1 }

     # SET REPRESENTATION OF "ch" +++++

}

############################################################################
#                             CONSOLE GREETING                             #
# This is printed in normal (non-batch/non-silent) mode, but only if the   #
# debug to log file option is OFF.                                         #
############################################################################
sub print_console_greeting {

     print STDOUT "\n";
     print STDOUT "\n===============================================================================";
     print STDOUT "\n= Perkins v$version";
     print STDOUT "\n= Scott Sadowsky · ssadowsky at g mail dot com";
     print STDOUT "\n===============================================================================";
     print STDOUT "\n";

     if   ( $lang eq "es" ) { $user_message = "El archivo a transcribir (\"$input_filename\") se leyó exitosamente..."; }
     else                   { $user_message = "The file to be transcribed (\"$input_filename\") was successfully read..."; }
     print STDOUT "\n$user_message";

     if ( $config_file_present == 1 ) {
          if   ( $lang eq "es" ) { $user_message = "El archivo de configuración (\"$config_filename\") fue procesado exitosamente..."; }
          else                   { $user_message = "The configuration file (\"$config_filename\") was successfully processed..."; }
          print STDOUT "\n$user_message\n";
     }

     if ( ( $use_config_file == 1 ) && ( $config_file_present == 0 ) ) {

          if   ( $lang eq "es" ) { $user_message = "** ADVERTENCIA: No se pudo procesar el archivo de configuración externo."; }
          else                   { $user_message = "** WARNING: The configuration file could not be processed."; }
          print STDOUT "\n$user_message";

          if   ( $lang eq "es" ) { $user_message = "**              Se utilizarán los valores preconfigurados..."; }
          else                   { $user_message = "**              The default configuration will be used..."; }
          print STDOUT "\n$user_message";
     }

     # Determine output mode label
     my $out_mode;
     if    ( $output_CV     == 1 ) { $out_mode = "CV"; }
     elsif ( $output_CVG    == 1 ) { $out_mode = "CVG"; }
     elsif ( $output_CVNLRG == 1 ) { $out_mode = "CVNLRG"; }
     elsif ( $output_manner == 1 ) { $out_mode = "Manner of articulation"; }
     elsif ( $output_place  == 1 ) { $out_mode = "Place of articulation"; }
     elsif ( $voicing       == 1 ) { $out_mode = "Voicing"; }
     else                          { $out_mode = "Phonemic (IPA)"; }

     ##########################################################################
     # SETTINGS TABLE                                                         #
     # Three-column layout: each cell holds "Label: value".                   #
     # Label column: 20 visual chars. Value: 1 char for booleans, wider for   #
     # string values (which span all 3 columns on a full-width row).          #
     # Total width: 3*(20+2+1+2)+4 = 79 chars (fits 80-column terminals).     #
     # CH shortcuts: 2-column, label col 30, total 73 chars.                  #
     # Values: green = default, yellow = from perkins.ini, orange = CLI flag. #
     # Section names print in light blue on a blank line before the rule.     #
     ##########################################################################
     {
          # vis_len: strip Unicode combining marks so IPA labels pad correctly.
          sub vis_len {
               use Unicode::Normalize 'NFD';
               my $s = NFD(shift // '');
               $s =~ s/\p{M}//g;
               return length($s);
          }

          # Geometry
          my $LC  = 20;                   # label column visual width (non-CH)
          my $CI  = $LC + 2 + 1;         # cell interior: label + ': ' + 1 value = 23
          my $div = ( '+' . '-' x ($CI + 2) ) x 3 . '+';   # 79-char divider

          my $LC2 = 30;                   # label column for CH shortcuts
          my $CI2 = $LC2 + 2 + 1;
          my $div2 = ( '+' . '-' x ($CI2 + 2) ) x 2 . '+'; # 73-char divider

          # Format a value with source-aware colour:
          #   green      = default value (unchanged from compiled-in default)
          #   bold yellow = set by perkins.ini
          #   red         = set by a command-line flag
          # Source detection:
          #   ini:  %_SET_BY_INI{var} is set in the ini reader loop
          #   CLI:  %_VAL_AFTER_CLI{var} differs from %_VAL_DEFAULT{var}
          #   default: neither of the above
          # src_color($varname): return the Term::ANSIColor colour string
          # for the source of this variable's current value.
          sub src_color {
               my $var  = shift;
               my $def  = $main::_VAL_DEFAULT{$var}   // '';
               my $acli = $main::_VAL_AFTER_CLI{$var} // '';
               return $main::_SET_BY_INI{$var}    ? 'bold yellow'
                    : ("$acli" ne "$def")          ? 'red'
                    :                                'green';
          }

          sub fmt_val {
               my ($var, $val) = @_;
               my $s = defined($val) ? "$val" : '';
               return safe_colored($s, src_color($var));
          }

          # Three-column row. @items = (label, varname, value,  x3).
          # Empty label → blank cell.
          sub row3 {
               my ($lc, @items) = @_;
               my $ci = $lc + 2 + 1;
               my $out = '';
               for my $i (0 .. 2) {
                    my $lbl = $items[$i * 3]       // '';
                    my $var = $items[$i * 3 + 1]   // '';
                    my $val = $items[$i * 3 + 2]   // '';
                    if ($lbl eq '') {
                         $out .= '| ' . ' ' x $ci . ' ';
                    } else {
                         my $pad = $lc - vis_len($lbl);
                         $pad = 0 if $pad < 0;
                         my $c = src_color($var);
                         $out .= '| ' . safe_colored($lbl, $c) . ' ' x $pad . ': ' . fmt_val($var, "$val") . ' ';
                    }
               }
               print STDOUT "\n$out|";
          }

          # Two-column row for CH shortcuts (wider labels).
          # @items = (label, varname, value,  x2).
          sub row2 {
               my ($lc, @items) = @_;
               my $ci = $lc + 2 + 1;
               my $out = '';
               for my $i (0 .. 1) {
                    my $lbl = $items[$i * 3]       // '';
                    my $var = $items[$i * 3 + 1]   // '';
                    my $val = $items[$i * 3 + 2]   // '';
                    if ($lbl eq '') {
                         $out .= '| ' . ' ' x $ci . ' ';
                    } else {
                         my $pad = $lc - vis_len($lbl);
                         $pad = 0 if $pad < 0;
                         my $c = src_color($var);
                         $out .= '| ' . safe_colored($lbl, $c) . ' ' x $pad . ': ' . fmt_val($var, "$val") . ' ';
                    }
               }
               print STDOUT "\n$out|";
          }

          # Full-width string-value row (spans all 3 columns).
          # Args: label, varname, value.
          sub row_str {
               my ($lbl, $var, $val, $div, $LC) = @_;
               my $inner = length($div) - 2;          # 77 chars
               my $lpad  = $LC - vis_len($lbl);
               $lpad = 0 if $lpad < 0;
               my $fval  = fmt_val($var, $val // '');
               # entry length for padding must use raw value (no ANSI codes)
               my $raw_entry = $lbl . ' ' x $lpad . ': ' . ($val // '');
               my $rpad  = $inner - 2 - length($raw_entry);
               $rpad = 0 if $rpad < 0;
               my $c   = src_color($var);
               print STDOUT "\n| " . safe_colored($lbl, $c) . ' ' x $lpad . ': ' . $fval . ' ' x $rpad . ' |';
          }

          # Section separator: blank line + name in cyan + divider.
          sub sect {
               my ($name, $d) = @_;
               print STDOUT "\n\n" . safe_colored($name, 'cyan') . "\n$d";
          }

          # ── Print the table ───────────────────────────────────────────────
          my $key = "Value color code: "
               . safe_colored("default", "green")      . " = green,  "
               . safe_colored("config file", "bold yellow") . " = yellow,  "
               . safe_colored("command line flags", "red") . " = red";
          print STDOUT "\n$key";
          print STDOUT "\n";
          print STDOUT "\n" . safe_colored('ACTIVE SETTINGS', 'bold cyan') . "\n$div";

          sect( 'PROGRAM BEHAVIOR', $div );
          row3( $LC,
               'Debug', 'debug', $debug,
               'Debug syllab. sub', 'debug_syllab_sub', $debug_syllab_sub,
               'Debug to logfile', 'debug_to_logfile', $debug_to_logfile );
          row3( $LC,
               'Silent mode', 'silent_mode', $silent_mode,
               'Batch mode', 'batch_mode', $batch_mode,
               '','' );
          print STDOUT "\n$div";

          sect( 'META OPTIONS', $div );
          row3( $LC,
               'Corpus/running text', 'corpus_running_text', $corpus_running_text,
               'Syllable list', 'syllable_list', $syllable_list,
               'MFA format', 'mfa_format', $mfa_format );
          row3( $LC,
               'Phonword format', 'phonword_format', $phonword_format,
               'VRT format', 'vrt_format', $vrt_format,
               '','' );
          print STDOUT "\n$div";

          sect( 'OUTPUT FORMAT', $div );
          row3( $LC,
               'Phonemic (IPA)', 'output_PHON', $output_PHON,
               'CV skeleton', 'output_CV', $output_CV,
               'CVG skeleton', 'output_CVG', $output_CVG );
          row3( $LC,
               'CVNLRG skeleton', 'output_CVNLRG', $output_CVNLRG,
               'Manner of artic.', 'output_manner', $output_manner,
               'Place of artic.', 'output_place', $output_place );
          row3( $LC,
               'Voicing', 'voicing', $voicing,
               '','' ,               '','' );
          print STDOUT "\n$div";

          sect( 'PHONEMES', $div );
          row3( $LC,
               'Multichars', 'multichars', $multichars,
               'TR is group', 'tr_is_group', $tr_is_group,
               'CH/DZH retracted', 'ch_dzh_retracted', $ch_dzh_retracted );
          row3( $LC,
               'Use ligatures', 'use_ligatures', $use_ligatures,
               '1-char CH symbol', 'use_one_char_ch_symbol', $use_one_char_ch_symbol,
               'YE = fricative', 'ye_phoneme_is_fricative', $ye_phoneme_is_fricative );
          row3( $LC,
               'YE = affricate', 'ye_phoneme_is_affricate', $ye_phoneme_is_affricate,
               '1-char YE symbol', 'use_one_char_ye_symbol', $use_one_char_ye_symbol,
               'Dental diacritics', 'use_dental_diacr', $use_dental_diacr );
          row3( $LC,
               'Epenthetic G', 'add_epenthetic_g', $add_epenthetic_g,
               '','' ,               '','' );
          print STDOUT "\n$div";

          sect( 'CH SHORTCUTS', $div2 );
          row2( $LC2,
               "CH: single char  (\x{02A7})", 'ch_is_single_char', $ch_is_single_char,
               "CH: retracted + lig  (t\x{0320}\x{0361}\x{0283})", 'ch_is_retracted_with_ligature', $ch_is_retracted_with_ligature );
          row2( $LC2,
               "CH: retracted no lig  (t\x{0320}\x{0283})", 'ch_is_retracted_no_ligature', $ch_is_retracted_no_ligature,
               "CH: not retracted + lig  (t\x{0361}\x{0283})", 'ch_not_retracted_with_ligature', $ch_not_retracted_with_ligature );
          row2( $LC2,
               "CH: not retracted no lig  (t\x{0283})", 'ch_not_retracted_no_ligature', $ch_not_retracted_no_ligature,
               '','' );
          print STDOUT "\n$div2";

          sect( 'GLIDES', $div );
          row3( $LC,
               'Glides w/ diacritics', 'glides_with_diacritics', $glides_with_diacritics,
               'Non-syl /u/ diacr', 'non_syl_u_with_u_diacr', $non_syl_u_with_u_diacr,
               'Non-syl /i/ diacr', 'non_syl_i_with_i_diacr', $non_syl_i_with_i_diacr );
          print STDOUT "\n$div";

          sect( 'STRESS', $div );
          row3( $LC,
               'Stress with tildes', 'stress_using_tildes', $stress_using_tildes,
               'No stress marks', 'no_stress_marks', $no_stress_marks,
               'Non-IPA apostrophes', 'non_ipa_apostrophes', $non_ipa_apostrophes );
          print STDOUT "\n$div";

          sect( 'NARROW TRANSCRIPTION', $div );
          row3( $LC,
               'Narrow transcription', 'narrow_transcription', $narrow_transcription,
               '','' ,                '','' );
          print STDOUT "\n$div";

          sect( 'SYLLABLES', $div );
          row3( $LC,
               'Syllable dots', 'insert_syllable_dots', $insert_syllable_dots,
               'Split at syllables', 'split_at_syllables', $split_at_syllables,
               'Syllabify by sent.', 'syllabify_by_sentence', $syllabify_by_sentence );
          row3( $LC,
               'Dots are spaces', 'syllable_dots_are_spaces', $syllable_dots_are_spaces,
               '','' ,                '','' );
          print STDOUT "\n$div";

          sect( 'PAUSES', $div );
          row3( $LC,
               'IPA pause symbols', 'ipa_pause_symbols', $ipa_pause_symbols,
               'Long pause = ||', 'ipa_long_pause_two_singles', $ipa_long_pause_two_singles,
               'Comma pauses', 'add_comma_pauses', $add_comma_pauses );
          row3( $LC,
               'Colon pauses', 'add_colon_pauses', $add_colon_pauses,
               'Semicolon pauses', 'add_semicolon_pauses', $add_semicolon_pauses,
               'Sentence breaks', 'add_sentence_breaks', $add_sentence_breaks );
          row3( $LC,
               'Paragraph breaks', 'add_paragraph_breaks', $add_paragraph_breaks,
               'Ellipsis pauses', 'add_ellipsis_pauses', $add_ellipsis_pauses,
               'Bracket pauses', 'add_bracket_pauses', $add_bracket_pauses );
          row3( $LC,
               'Paren pauses', 'add_paren_pauses', $add_paren_pauses,
               '','' ,                '','' );
          print STDOUT "\n$div";

          sect( 'NUMBERS', $div );
          row3( $LC,
               'Numerals to words', 'numerals_to_words', $numerals_to_words,
               'Narrow year ranges', 'narrow_year_ranges', $narrow_year_ranges,
               'Broad year ranges', 'broad_year_ranges', $broad_year_ranges );
          row3( $LC,
               'BC dates included', 'bc_dates_included', $bc_dates_included,
               'All year ranges', 'all_year_ranges', $all_year_ranges,
               'Times with colon', 'times_with_colon', $times_with_colon );
          row_str( 'Numeral symbol', 'num_symbol', $num_symbol, $div, $LC );
          row_str( 'Decimal symbol', 'decimal_symbol', $decimal_symbol, $div, $LC );
          print STDOUT "\n$div";

          sect( 'ODD CHARACTERS', $div );
          row3( $LC,
               'Fix umlauts', 'fix_umlauts', $fix_umlauts,
               'Fix grave accents', 'fix_grave_accents', $fix_grave_accents,
               'Fix circumflexes', 'fix_circumflexes', $fix_circumflexes );
          row3( $LC,
               'Fix nasal tildes', 'fix_nasal_tildes', $fix_nasal_tildes,
               '','' ,                '','' );
          print STDOUT "\n$div";

          sect( 'SUBSTITUTIONS & MISC', $div );
          row3( $LC,
               'Process URLs', 'process_urls', $process_urls,
               'Process email', 'process_email', $process_email,
               'Keep paragraphs', 'keep_paragraphs', $keep_paragraphs );
          row3( $LC,
               'Vertical output', 'vertical_output', $vertical_output,
               'Triple vwls→double', 'triple_vowels_to_double', $triple_vowels_to_double,
               '','' );
          row_str( 'Currency symbol', 'moneda', $moneda, $div, $LC );
          row_str( 'RUT K mode', 'rut_k_mode', $rut_k_mode, $div, $LC );
          row_str( 'Slash', 'slash', $slash, $div, $LC );
          row_str( 'Name for V', 'name_for_v', $name_for_v, $div, $LC );
          print STDOUT "\n$div";

          sect( 'ADVANCED', $div );
          row3( $LC,
               'Upper case', 'upper_case', $upper_case,
               'Kill common words', 'kill_common_words', $kill_common_words,
               'Space betw. phonemes', 'space_between_phonemes', $space_between_phonemes );
          row3( $LC,
               'Word plus phonemes', 'word_plus_phonemes', $word_plus_phonemes,
               '','' ,                '','' );
          print STDOUT "\n$div";

          print STDOUT "\n";
     }

     if   ( $lang eq "es" ) { $user_message = "PROCESANDO..."; }
     else                   { $user_message = "PROCESSING..."; }
     print STDOUT "\n$user_message\n";

}    # END SUBROUTINE: PRINT CONSOLE GREETING


#################################################################################
#                                                                               #
#   SUBROUTINE: PROCESS INTERNET STUFF                                          #
#   Note: Doesn't process certain characters in URLs (% ! = & ? # etc.), but    #
#         simply eliminates them.                                               #
#                                                                               #
#################################################################################
sub process_internet_stuff {

     my $current_item = $_[0];

     # <-- NEW IN 393
     # EXPERIMENTAL!
     my @current_segments = split /\s/, $current_item;

     foreach my $current_segment (@current_segments) {

          # END NEW IN 393 -->

          #print "\n==>PROCESS-INTERNET-STUFF--START=$current_item\n";    # AD-HOC DEBUG

          ############################################################################
          # PROCESS URLS as linguistic strings, if desired                           #
          ############################################################################

          if ( $process_urls == 1 ) {

               # Extract URLs from text                                              #

               if (

                    # NOTE: Added "?" after "(\/\/)" in the following expression in 396
                    $current_segment =~
m/<?((http|https|ftp|sftp|news|gopher|mailto):(\/\/)?|(www\.))([a-zA-Z0-9_\$\&\+\,\/\:\;\=\?\@\#\%\{\}\|\\\^\~\[\]\`\'\"\!\*\(\)\+\.\>\-]+)/
                 )
               {
                    # PROTOCOLS (Careful with ordering!)
                    $current_segment =~ s{sftp:\/\/}{eseefetepé dos puntos $slash $slash }g;
                    $current_segment =~ s{https:\/\/}{achetetepeése dos puntos $slash $slash }g;
                    $current_segment =~ s{http:\/\/}{achetetepé dos puntos $slash $slash }g;
                    $current_segment =~ s{ftp:\/\/}{efetepé dos puntos $slash $slash }g;
                    $current_segment =~ s{news:\/\/}{nius dos puntos $slash $slash }g;
                    $current_segment =~ s{gopher:\/\/}{gófer dos puntos $slash $slash }g;
                    $current_segment =~ s{mailto:}{meiltu dos puntos }g;

                    # Odd characters
                    $current_segment =~ s/\`/ acento grave /g;
                    $current_segment =~ s/\'/ apóstrofo /g;
                    $current_segment =~ s/\@/ arroba /g;
                    $current_segment =~ s/\*/ asterisco /g;
                    $current_segment =~ s/\\/ bákeslatch /g;
                    $current_segment =~ s/\|/ barra vertical /g;
                    $current_segment =~ s/\^/ circunflejo /g;
                    $current_segment =~ s/\,/ coma /g;
                    $current_segment =~ s/\"/ comillas /g;
                    $current_segment =~ s/\[/ corchete de apertura /g;
                    $current_segment =~ s/\]/ corchete de cierre /g;
                    $current_segment =~ s/\:/ dos puntos /g;
                    $current_segment =~ s/\_/ guión bajo /g;
                    $current_segment =~ s/\-/ guión /g;
                    $current_segment =~ s/\{/ llave de apertura /g;
                    $current_segment =~ s/\}/ llave de cierre /g;
                    $current_segment =~ s/\(/ paréntesis de apertura /g;
                    $current_segment =~ s/\)/ paréntesis de cierre /g;
                    $current_segment =~ s/\./ punto /g;
                    $current_segment =~ s/\;/ puntoycoma /g;
                    $current_segment =~ s/\!/ signo de exclamación /g;
                    $current_segment =~ s/\?/ signo de interrogación /g;
                    $current_segment =~ s/\%/ signo de porcentaje /g;
                    $current_segment =~ s/\#/ signo gato /g;
                    $current_segment =~ s/\=/ signo igual a /g;
                    $current_segment =~ s/\+/ signo mas /g;
                    $current_segment =~ s/\$/ signo peso /g;
                    $current_segment =~ s/\&/ signo y /g;
                    $current_segment =~ s/\// $slash /g;
                    $current_segment =~ s/\~/ tilde /g;

                    #print "==>PROCESS-INTERNET-STUFF-AFTPROT=$current_segment\n";    # AD-HOC DEBUGGING

                    # TLDs                                                           #

                    # TLDs with 3+ letters
                    $current_segment =~ s/ punto aero(\W|$)/ punto aero $1/g;
                    $current_segment =~ s/ punto asia(\W|$)/ punto asia $1/g;
                    $current_segment =~ s/ punto biz(\W|$)/ punto bis $1/g;
                    $current_segment =~ s/ punto cat(\W|$)/ punto kat $1/g;
                    $current_segment =~ s/ punto com(\W|$)/ punto kom $1/g;
                    $current_segment =~ s/ punto coop(\W|$)/ punto c o o p $1/g;
                    $current_segment =~ s/ punto edu(\W|$)/ punto e d u $1/g;
                    $current_segment =~ s/ punto gob(\W|$)/ punto g o b $1/g;
                    $current_segment =~ s/ punto gov(\W|$)/ punto g o v $1/g;
                    $current_segment =~ s/ punto info(\W|$)/ punto info $1/g;
                    $current_segment =~ s/ punto int(\W|$)/ punto i n t $1/g;
                    $current_segment =~ s/ punto jobs(\W|$)/ punto jobs $1/g;
                    $current_segment =~ s/ punto mil(\W|$)/ punto m i l $1/g;
                    $current_segment =~ s/ punto mobi(\W|$)/ punto mobi $1/g;
                    $current_segment =~ s/ punto museum(\W|$)/ punto muséum $1/g;
                    $current_segment =~ s/ punto name(\W|$)/ punto  $1/g;
                    $current_segment =~ s/ punto net(\W|$)/ punto net $1/g;
                    $current_segment =~ s/ punto org(\W|$)/ punto o r g $1/g;
                    $current_segment =~ s/ punto pro(\W|$)/ punto pro $1/g;
                    $current_segment =~ s/ punto tel(\W|$)/ punto tel $1/g;
                    $current_segment =~ s/ punto travel(\W|$)/ punto trável $1/g;

