                    $current_segment =~ s/ punto vg(\W|$)/ punto v g $1/g;
                    $current_segment =~ s/ punto vi(\W|$)/ punto v i $1/g;
                    $current_segment =~ s/ punto vn(\W|$)/ punto v n $1/g;
                    $current_segment =~ s/ punto vu(\W|$)/ punto v u $1/g;
                    $current_segment =~ s/ punto wf(\W|$)/ punto w f $1/g;
                    $current_segment =~ s/ punto ws(\W|$)/ punto w s $1/g;
                    $current_segment =~ s/ punto ye(\W|$)/ punto igriega  $1/g;
                    $current_segment =~ s/ punto yt(\W|$)/ punto igriega  $1/g;
                    $current_segment =~ s/ punto za(\W|$)/ punto z a $1/g;
                    $current_segment =~ s/ punto zm(\W|$)/ punto z m $1/g;
                    $current_segment =~ s/ punto zw(\W|$)/ punto z w $1/g;
               }

               #print "==>PROCESS-INTERNET-STUFF-AFT.xx=$current_segment\n";    # AD-HOC DEBUGGING
          }
          else {
               #######################################################################
               # ELIMINATE URLs, replacing them with a space                         #
               #######################################################################
               $current_segment =~ s/<?(http|https|ftp|sftp|gopher|news|mailto|file):\/\/\S+/ /g;
          }

          ############################################################################
          # PROCESS e-mail addresses as linguistic strings, if desired               #
          ############################################################################

          if ( $process_email == 1 ) {

               #if ( $current_segment =~ m/[\w\-\.\+]+\@[\w.]+/ ) {
               if ( $current_segment =~ m/[\w\-\.\+]+\@[\w.]+/ ) {

                    $current_segment =~ s/\-/ guión /g;
                    $current_segment =~ s/\@/ arroba /g;
                    $current_segment =~ s/\_/ guión bajo /g;
                    $current_segment =~ s/\./ punto /g;
                    $current_segment =~ s/\+/ signo mas /g;

                    #print STDOUT "***PROCESS E-MAIL subroutine executed\n";
               }
          }
          else {
               #######################################################################
               # ELIMINATE e-mail addresses, replacing them with a space             #
               #######################################################################
               $current_segment =~ s/[\w\-\.\+]+\@[\w]+\.?[\w]+\.?[\w]+\.?[\w]+(\.?)[\w]+/ /g;

               #print STDOUT "***ELIMINATE E-MAIL subroutine executed\n";       # AD-HOC DEBUGGING
          }

          #print "==>PROCESS-INTERNET-STUFF---END=$current_segment\n\n";        # AD-HOC DEBUGGING

          # CHANGE "." WHEN IT IS SURROUNDED BY LETTERS TO "PUNTO".  FOR URLs, MAINLY

          $current_segment =~ s/([a-zA-Z]+)\.([a-zA-Z]+)/$1 punto $2/g;
          $current_segment =~ s/([a-zA-Z]+)\.([a-zA-Z]+)/$1 punto $2/g;          # Not sure why the prev line doesn't catch all instances...
          $current_segment =~ s/([a-zA-Z]+)\.([a-zA-Z]+)/$1 punto $2/g;          # This is here just for good measure.
          $current_segment =~ s/([a-zA-Z]+)\.([a-zA-Z]+)/$1 punto $2/g;          # Ditto.
          $current_segment =~ s/([a-zA-Z]+)\.([a-zA-Z]+)/$1 punto $2/g;          # Ditto.

          #print "==>EXPER-INT-STUFF-SPLIT----END=$current_segment\n";                 # AD-HOC DEBUGGING
     }

     $current_item = join( " ", @current_segments );

     return ($current_item);

}    # END SUBROUTINE: PROCESS INTERNET STUFF

##############################################################################
#                                                                            #
#   SUBROUTINE: FIX MISCELLANEOUS PUNCTUATION                                #
#                                                                            #
##############################################################################
sub fix_misc_punctuation {

     # Read value passed into subroutine and assign it to $current_item
     my $current_item = $_[0];

     #   ADD SPACE AFTER PERIOD+BRACKETS. Prevents problems with .[ and .( in cites.
     $current_item =~ s/\.[\[\]\{\}\(\}]/\. /g;

     # REMOVE QUOTATION MARKS
     $current_item =~ s/"//g;

     # ELIMINATE ELLIPSES AT BEGINNING OF LINE
     $current_item =~ s/^\.\.\.//g;

     # ADD SPACES AROUND ELLIPSES
     $current_item =~ s/\.\.\./ \.\.\. /g;

     # ADD SPACE AFTER ). COMBINATION
     $current_item =~ s/\)\./\)\. /g;

     # ADD SPACE AFTER )
     $current_item =~ s/\)/\) /g;

     # ADD SPACE BEFORE (
     $current_item =~ s/\(/ \(/g;

     # print "\n==>  DASH PROCESSING BEF:: $current_item";   # AD-HOC DEBUG

     ##############################################################################
     # Replace em and en dashes with "--"                                         #
     ##############################################################################
     $current_item =~ s//--/g;
     $current_item =~ s/–/--/g;
     $current_item =~ s/—/--/g;

     ##############################################################################
     # REMOVE SINGLE DASH WITH LETTERS TOUCHING ON BOTH SIDES: FOR COMPOUND WORDS #
     # (e.g. "tetra-pack", "Bío-Bío", "palato-alveolar".                          #
     ##############################################################################
     $current_item =~ s/([a-z])-([a-z])-([a-z])/$1 $2 $3/g;    # For possible phrases with two dashes
     $current_item =~ s/([a-z])-([a-z])/$1 $2/g;

     ############################################################################
     # SEPARATE LETTERS FROM NUMBERS IN WORDS CONSISTING OF LETTERS+NUMBERS     #
     # OR LETTER + DASH + NUMBER (e.g. F0, mc2, t1000, T-1000)                  #
     ############################################################################
     #print STDOUT "SEPARATE-LETTS-FROM-NUMS-BEF:$current_item\n";         # AD-HOC DEBUG

     # DISABLED: Alphanumeric-split rules convert "abc123"\xe2\x80\x94 spec requires identifiers to pass through.
     # $current_item =~ s/(\W|^)([a-záéíóúñ]+)([0-9]+)(\W|$)/ $1$2 $3$4 /g;
     # $current_item =~ s/(\W|^)([a-záéíóúñ]+)([0-9]+)(\W|$)/ $1$2 $3$4 /g;  # repetition disabled

     # DISABLED: Letter+Dash+Numbers
     # $current_item =~ s/(\W|^)([a-záéíóúñ]+)\-([0-9]+)(\W|$)/ $1$2 $3$4 /g;

     #print STDOUT "SEPARATE-LETTS-FROM-NUMS-AFT:$current_item\n";         # AD-HOC DEBUG

     ##############################################################################
     # CHANGE MATHEMATICAL OPERATORS BETWEEN NUMERALS INTO WORDS                  #
     # (e.g. "12.345.678-9", 10-2=6)                                              #
     ##############################################################################
     # RUT handler: this fires only if normalize_structured_tokens section 6
     # missed the RUT (e.g. non-standard format). Since normalize now runs first
     # and section 6 handles all standard RUT formats, this is a safety fallback.
     # Disabled to prevent partial expansion (12.345.678 with dots still present
     # would then be misread as a large number by convert_numerals_to_words).
     # $current_item =~ s/([0-9])\.([0-9]{3})\.([0-9]{3})( |)-( |)([0-9])/$1.$2.$3 guión $6/g;

     $current_item =~ s/([0-9])( |)\-( |)([0-9])/$1 menos $4/g;
     $current_item =~ s/([0-9])( |)=( |)([0-9])/$1 es igual a $4/g;
     $current_item =~ s/([0-9])( |)\+( |)([0-9])/$1 más $4/g;
     $current_item =~ s/([0-9])( |)\/( |)([0-9])/$1 dividido por $4/g;
     $current_item =~ s/([0-9])( |)\*( |)([0-9])/$1 multiplicado por $4/g;

     $current_item =~ s/([0-9])( |)×( |)([0-9])/$1 multiplicado por $4/g;
     $current_item =~ s/([0-9])( |)÷( |)([0-9])/$1 dividido por $4/g;
     $current_item =~ s/±( |)([0-9])/ más o menos $1$2/g;                  # This symbol can just have a num after it

     ############################################################################
     # CONVERT 2 or 3 DASHES INTO COMMA (TO MAKE PAUSE).                        #
     # (e.g. "se fue -- rápidamente --- y lloró".                               #
     ############################################################################
     $current_item =~ s/\-\-\-/, /g;
     $current_item =~ s/\-\-/, /g;

     ###########################################################################
     # CONVERT A MINUS SIGN ATTACHED TO A DIGIT (NEGATIVE NUMBER) INTO "MENOS" #
     # *BEFORE* the next rule turns remaining dashes into commas. This must    #
     # happen here, while the minus sign can still be distinguished from a     #
     # genuine comma. Once it becomes ", " there is no way to tell a real      #
     # comma + number (e.g. "Allá, 400 personas") from a minus-sign-turned-    #
     # comma (e.g. "es -400"), which previously caused "Allá, 400" to be       #
     # misread as a negative number further down the pipeline.                 #
     #                                                                         #
     # The optional "\$?" lets this also catch negative currency amounts       #
     # (e.g. "-$200.000"). The "$" itself is matched via lookahead, not        #
     # consumed, so it's left in place for change_some_symbols_to_words() /    #
     # the currency-amount handling in convert_numerals_to_words() to convert  #
     # later (e.g. "-$200.000" -> "menos $200.000" -> "menos doscientos mil    #
     # " . $moneda . " " (whatever currency name is configured, "pésos" by     #
     # default)).                                                              #
     ###########################################################################
     $current_item =~ s/(^|\s)-(?=\$?[0-9])/${1}menos /g;

     ###########################################################################
     # CONVERT REMAINING CASES OF 1 DASH INTO COMMA + SPACE (TO MAKE PAUSE)    #
     ###########################################################################
     $current_item =~ s/\-/, /g;

     # print "\n==  DASH PROCESSING AFT:: $current_item";   # DEBUG

     return ($current_item);

}    # END SUBROUTINE: FIX MISC PUNCTUATION

#################################################################################
#                                                                               #
#   SUBROUTINE: EXPAND ABBREVIATIONS IN ORTHOGRAPHIC FORM                       #
#                                                                               #
#################################################################################
############################################################################
# SUBROUTINE: PROTECT_ABBREVIATION_PERIODS                                 #
# Called by normalize_structured_tokens() before it turns a period after a #
# word into an utterance boundary. The period of each abbreviation that    #
# expand_abbreviations_ortho() knows becomes \x{E000}, which no step in    #
# between touches; expand_abbreviations_ortho() turns it back into a       #
# period and expands the abbreviation.                                     #
# Words that are also ordinary words at the end of a sentence (a, e, i, o, #
# u, y, as, se, so, gen, vid) are protected only inside a longer          #
# abbreviation (bs. as.), and "no." only before a number (no. 5). "etc."   #
# is spelled out here and keeps its period, since it so often ends a       #
# sentence. A single letter with a period is left alone: most (J., p.) and #
# the other tokens of the built-in tables (Dr.) are read by               #
# apply_builtin_exceptions() before this runs, and the rest (plan B.) are  #
# spelled out later. Capitals (EE. UU.) are read by prelc_pass().          #
############################################################################

sub protect_abbreviation_periods {
     my $t = shift;
     our $ABBREVIATION_PERIOD_RE;
     unless ( defined $ABBREVIATION_PERIOD_RE ) {
          my @words = qw(
               contralmte almte comod comte confr coord cónfr depto excmo presb profa
               teléf afma afmo alfz apdo atta atte atto avda bibl cmdt cmte cnel conf
               ctvo cént cónf diag dicc dpto ejem gral ibíd ilmo incl lcda lcdo ltda ltdo
               mons ntra ntro pbro pdta pdte plza prof prov párr sgto srta univ art arz
               bco cap cfr cit cta cte ctv cía cód der dir dra dña edo etc fdo fed fig
               izq lic loc máx mín nro núm ofc pza pág rte sig sra sta sto tel tte uds
               vda vdo vds vol aa av bs cc cf cp dd dn dr ee ej ff gr hh ib jj ms ne ob
               oo pg pp rr sr ss ud uu vd vs ál íd óp
          );
          $ABBREVIATION_PERIOD_RE = join( '|', @words );
     }
     my $P = "\x{E000}";
     $t =~ s/(?<![\p{L}\d])etc\.(?=\s|$)/etcétera./g;
     # Inside a longer abbreviation: followed by another short word with a
     # period (a. m., a. de j. c.) or preceded by one (i. e., bs. as.).
     $t =~ s/(?<![\p{L}\d])(a|e|i|o|u|y|as|se|so|gen|vid)\.(?=\s*(?:de\s+)?\p{L}{1,4}[.\x{E000}])/$1$P/g;
     $t =~ s/(?<=[\p{L}][.\x{E000}])(\s?)(a|e|i|o|u|y|as|se|so|gen|vid)\.(?=\s|$)/$1$2$P/g;
     $t =~ s/(?<![\p{L}\d])no\.(?=\s*\d)/no$P/g;
     $t =~ s/(?<![\p{L}\d])($ABBREVIATION_PERIOD_RE)\.(?=\s|$)/$1$P/g;
     return $t;
}

sub expand_abbreviations_ortho {

     my $current_item = $_[0];

     # Periods of abbreviations, protected by protect_abbreviation_periods().
     $current_item =~ s/\x{E000}/./g;

     #print STDOUT "NON-VRT_ABBREV-DEBUG-BEF:$current_item:\n";    # AD HOC DEBUG

     # ABBREVIATIONS WITH SLASHES
     $current_item =~ s/(\W|^)a\/c(\W)/$1a cuenta /g;
     $current_item =~ s/(\W|^)a\/f(\W)/$1a favor /g;
     $current_item =~ s/(\W|^)c\/u(\W)/$1cada uno /g;
     $current_item =~ s/(\W|^)s\/a(\W)/$1sin año /g;
     $current_item =~ s/(\W|^)s\/e(\W)/$1sin editorial /g;
     $current_item =~ s/(\W|^)s\/f(\W)/$1sin fecha /g;
     $current_item =~ s/(\W|^)s\/l(\W)/$1sin lugar /g;
     $current_item =~ s/(\W|^)s\/n(\W)/$1sin número /g;
     $current_item =~ s/(\W|^)v\/s(\W)/$1versus /g;
