     $current_item =~ s/(^|\.|,|:|;|"|-|‖|\[|\(|\{)pf($|\.|,|:|;|"|-|‖|\]|\)|\}|>)/$1PF$2/g;
     $current_item =~ s/(^|\.|,|:|;|"|-|‖|\[|\(|\{)sh($|\.|,|:|;|"|-|‖|\]|\)|\}|>)/$1SH$2/g;
     $current_item =~ s/(^|\.|,|:|;|"|-|‖|\[|\(|\{)uh($|\.|,|:|;|"|-|‖|\]|\)|\}|>)/$1UH$2/g;

